    CharMaxAttempts = 3,
    CharLockExpiry = 1800,
    SwitchRespawnTimeout = 4,

    -- Game 1.85: the server no longer respawns a dead fighter on its own. It
    -- sets CanRespawn on the body and waits for JoinService.Respawn, which is
    -- what the game's Respawn button fires. AutoRespawn presses it for us,
    -- but only while the bot is meant to be running (AutoState.wantOn).
    AutoRespawn = true,
    RespawnDelay = 0.4,         -- let the offer stand a moment before taking it
    RespawnRetry = 1.0,         -- the remote is silent on failure: ask again
    -- Game 1.85: Road Rage and House hand the caster a throwaway remote and
    -- expect a stream of aim points. AimReply answers with the target's feet.
    AimReply = true,

    -- ------------------------------------------------------------ tactics
    -- The model-based layer (v85). It replaces "cast whatever is ready and in
    -- range" with four rules that hold for every moveset: chain off a hit
    -- that is known to have landed, block on time-to-contact instead of on
    -- the swing, aim where the target will be, and never throw a cast the
    -- server is certain to refuse. Each piece has its own switch (HUD >
    -- Tactics) and its own counters in the LIFE END line, so its effect can
    -- be read out of a log rather than guessed.
    TacCombo = true,            -- chain a skill the moment a hit is confirmed
    TacComboStep = 4,           -- ... once CurrentM1 says the fourth swing is next (three are out)
    TacComboPatience = 1.6,     -- ... or the target has been held this long without the string advancing
    TacComboGap = 0.25,         -- seconds between two chained casts
    TacDiscipline = true,       -- in melee, keep skills for a confirmed hit
    TacNeutralGap = 4.0,        -- ... but still throw one unconfirmed this often
    TacGuard = true,            -- block on time-to-contact, before the swing shows
    TacGuardTTC = 0.38,         -- seconds to contact at which the block goes up
    TacGuardReach = 6.5,        -- studs at which a basic attack connects
    TacGuardSpeed = 12,         -- closing speed (studs/s) that counts as coming at us; base walk is 16
    TacGuardHold = 0.55,        -- how long a predicted block waits for the swing
    TacGuardRest = 1.4,         -- seconds before a prediction may fire again
    TacPunish = 1.1,            -- counterattack window after a blocked string
    TacLead = true,             -- aim where the target will be, not where it is
    TacLeadSpeed = 140,         -- studs/s assumed for a projectile of unknown speed
    TacLeadMax = 0.7,           -- cap on the lead time, seconds
    TacLeadDist = 16,           -- cap on the lead distance, studs
    TacCastGate = true,         -- no casts while stunned or ragdolled
    TacVulnWeight = 14,         -- target-choice bonus for someone already stunned
    TacComboDelay = 0.14,       -- let a basic attack finish landing before chaining off it
    -- Movement (v86). The v85 log had the fighter moving backwards relative
    -- to its own facing for 60% of APPROACH_FAR, with no sprint, because the
    -- body was held on the target while the feet followed a path.
    TacFaceTravel = true,       -- face the way we are running until in fighting distance
    TacFaceDist = 14,           -- studs from the target at which the body squares up to it
    TacFaceFlee = 10,           -- when retreating, turn and run once the pursuer is this far
    TacFaceLerp = 0.28,         -- how fast the body turns onto the travel direction
    TacMoveDamp = true,         -- a goal that reverses our direction must persist before it is obeyed
    TacMoveDampFor = 0.2,       -- ... for this many seconds
    -- 64% of the blocks in the v85 log lasted 0.1 s or less and 78% never met
    -- a swing: the decision that raised them was gone on the next frame. A
    -- block that short absorbs nothing and still interrupts the attack.
    TacBlockKeep = true,        -- once raised, a block stays up at least TacBlockMin
    TacBlockMin = 0.3,
    -- Knowledge (v87). In the v86 log no move with twelve tries landed half
    -- the time: counters were thrown at people who were not attacking,
    -- blockable moves into raised guards, everything at bodies on the
    -- ground. Each move now has a family and researched facts (MoveFacts),
    -- and every cast is booked by what the target was doing when it was
    -- thrown, so the estimate corrects itself.
    Know = true,                -- gate and weigh every cast by its chance to land on the target as it is
    KnowMinP = 0.2,             -- below this chance a cast is withheld
    KnowSureP = 0.45,           -- at or above this, a move is used on purpose against a guard / a body on the ground
    KnowPriorWeight = 4,        -- how many casts the starting belief is worth
    KnowSeedCap = 8,            -- how many casts the pre-v87 career totals are worth
    KnowProbe = true,           -- ask open questions (never researched, hardly tried) a few times a life
    KnowProbePerLife = 3,
    KnowProbeTries = 3,
    KnowProbeGap = 8,
    KnowCounter = true,         -- counters are thrown into a swing, and only into a swing
    KnowCounterReach = 10,
    KnowM1Hold = true,          -- no basic attacks into a raised guard or at a body on the ground
    KnowFlankWindow = 0.9,      -- ... except for this long after a side dash (a guard covers the front only)
