        beam       = { free = 0.35, block = 0.10, stun = 0.80, rag = 0.20, wake = 0.32, swing = 0.45, air = 0.28 },
        aoe_self   = { free = 0.35, block = 0.15, stun = 0.85, rag = 0.35, wake = 0.28, swing = 0.45, air = 0.20 },
        aoe_point  = { free = 0.25, block = 0.12, stun = 0.75, rag = 0.35, wake = 0.25, swing = 0.38, air = 0.15 },
        grab       = { free = 0.38, block = 0.45, stun = 0.80, rag = 0.08, wake = 0.30, swing = 0.25, air = 0.12 },
        counter    = { free = 0.03, block = 0.02, stun = 0.01, rag = 0.01, wake = 0.03, swing = 0.60, air = 0.03 },
        pull       = { free = 0.35, block = 0.15, stun = 0.75, rag = 0.12, wake = 0.30, swing = 0.40, air = 0.30 },
        summon     = { free = 0.30, block = 0.10, stun = 0.70, rag = 0.25, wake = 0.28, swing = 0.40, air = 0.20 },
        other      = { free = 0.30, block = 0.10, stun = 0.75, rag = 0.15, wake = 0.20, swing = 0.35, air = 0.20 },
    },
    -- families that are not thrown at somebody to hurt them
    PASSIVE = { buff = true, stance = true, mobility = true, domain = true },
    heldAt = {},
}
Know.PRIOR.trap = Know.PRIOR.aoe_point

-- What family a move belongs to, the researched line for it, and who says so.
function knowKind(name, rule)
    local key = senseMoveKey(name)
    local f = MoveFacts[key]
    if f and f.k then return f.k, f, "researched" end
    rule = rule or MoveRules[name] or DefaultRule
    if rule.summon then return "summon", f, "table" end
    if rule.selfBuff then return "buff", f, "table" end
    if rule.escape then return "mobility", f, "table" end
    if rule.trap then return "trap", f, "table" end
    local d = type(DangerByService) == "table" and DangerByService[key] or nil
    if d == "aoe" then return "aoe_self", f, "game files" end
    if d then return d, f, "game files" end
    -- nothing written down anywhere: go by what the machine has seen it do
    local o = type(MEM.facts) == "table" and MEM.facts[name] or nil
    if o and (o.mvN or 0) >= 4 and (o.mv or 0) / o.mvN >= 10 then return "rush", f, "observed" end
    local reach = rule.max or 40
    if reach >= 40 then return "projectile", f, "range" end
    if reach <= 14 then return "melee", f, "range" end
    return "rush", f, "range"
end

function knowBlocking(t)
    local i = getInfo(t)
    if i then
        if i:FindFirstChild("Block") or i:FindFirstChild("Blocking") then return true end
        if i:GetAttribute("Block") or i:GetAttribute("Blocking") then return true end
    end
    if Config.Sense and type(senseBlocking) == "function" and senseBlocking(t) then return true end
    return false
end

-- What the target is doing, in the one word the beliefs are keyed by.
function knowState(t)
    if not t then return "free" end
    -- asked once per candidate move per frame: answer from the last look
    local now = tick()
    if Know.stT == t and (now - (Know.stAt or 0)) < 0.05 then return Know.stV end
    local v = knowStateRaw(t)
    Know.stT, Know.stAt, Know.stV = t, now, v
    return v
end

function knowStateRaw(t)
    if isRagdolled(t) then return "rag" end
    if isStunned(t) then return "stun" end
    do  -- just got up: half a second in which melee does not stun them
        local r = Tac.track[t]
        if Config.TacWake and r and r.wokeAt and (tick() - r.wokeAt) < (Config.TacWakeWindow or 0.5) then return "wake" end
    end
    if knowBlocking(t) then return "block" end
    local th, h = getHRP(t), getHRP()
    if th and h then
        local v = tacVelocity(t)
        if (th.Position.Y - h.Position.Y) > 6 or math.abs(v.Y) > 14 then return "air" end
    end
    if isInSkill(t) or (type(senseMeleeSwing) == "function" and senseMeleeSwing(t)) then return "swing" end
    return "free"
end

-- The career totals from before v87 say how often a move landed but not on
-- whom. Nearly all of those casts were thrown raw, so they go in as evidence
-- about a free target, capped so new measurements soon outweigh them.
function knowSeed()
    Know.seeded = true
    if type(MEM.facts) ~= "table" then MEM.facts = {} end
    local g = MEM.global and MEM.global.moves
    if type(g) ~= "table" then return end
    for name, m in pairs(g) do
        if type(name) == "string" and type(m) == "table" and not name:find("^SPECIAL:")
           and (m.tries or 0) >= 4 and MEM.facts[name] == nil then
            local w = math.min(m.tries, Config.KnowSeedCap or 8)
            MEM.facts[name] = { n = 0, seeded = true,
                s = { free = { n = w, h = math.clamp((m.hits or 0) / m.tries, 0, 1) * w } } }
        end
    end
end

-- Chance that `name` lands on a target in `state`. Returns the chance, how
-- many real casts stand behind it, and whether research settles the matter.
function knowChance(name, state, kind, f)
    if not Know.seeded then knowSeed() end
    if not kind then kind, f = knowKind(name) end
    local prior = (Know.PRIOR[kind] or Know.PRIOR.other)[state] or 0.3
    local w = Config.KnowPriorWeight or 4
    local settled = false
    if f then
        if state == "block" and f.ub ~= nil then
            prior, w, settled = (f.ub and 0.62 or 0.04), w + 3, true
        elseif state == "rag" and f.rag ~= nil then
            prior, w, settled = (f.rag and 0.62 or 0.04), w + 3, true
        end
    end
    if kind == "counter" then settled = true end
    local o = type(MEM.facts) == "table" and MEM.facts[name] or nil
    local c = o and type(o.s) == "table" and o.s[state] or nil
    local n, h = c and c.n or 0, c and c.h or 0
    return (prior * w + h) / (w + n), n, settled
end

-- Measured wind-up and, for anything that flies, measured speed. Every
-- clean hit gives one (distance, delay) pair; the least-squares line through
-- them is delay = windup + distance / speed. Six hits spread over a dozen
-- studs are needed before the slope is believed; until then the mean stands.
function knowTiming(name)
    local o = type(MEM.facts) == "table" and MEM.facts[name] or nil
    if not o or (o.rn or 0) < 3 then return nil end
    local n, sd, st, sdd, sdt = o.rn, o.rd or 0, o.rt or 0, o.rdd or 0, o.rdt or 0
    local mean = st / n
    local var = sdd / n - (sd / n) ^ 2
    if n >= 6 and var >= 16 then
        local b = (n * sdt - sd * st) / (n * sdd - sd * sd)
        local a = (st - b * sd) / n
        if b > 0.0015 and b < 0.05 and a >= 0 and a < 1.5 then
            return mean, a, 1 / b
        end
    end
    return mean, nil, nil
end

-- May this move be thrown at this target now? Returns ok, the chance, why not.
function knowAllows(entry, t, d2d, ctx)
    if not Config.Know or not entry or not t then return true, 1, nil end
    local rule = entry.rule or DefaultRule
    local kind, f = knowKind(entry.name, rule)
    if kind == "domain" then return knowDomainSafe(t, d2d) end
    if Know.PASSIVE[kind] then return true, 1, nil end
    local now = tick()
    -- a counter does nothing unless somebody is hitting us: it is thrown by
    -- the guard (knowTryCounter), never picked as an attack
    if kind == "counter" then return false, 0, "counter with nobody swinging" end
    local state = knowState(t)
    local p, n, settled = knowChance(entry.name, state, kind, f)
    if p < (Config.KnowMinP or 0.2) then
        -- an open question (nothing researched, hardly tried) may be asked a
        -- few times a life: that is how the answer gets into the memory
        if Config.KnowProbe and not settled and n < (Config.KnowProbeTries or 3)
           and (Life.knowProbes or 0) < (Config.KnowProbePerLife or 3)
           and (now - (Bot.KnowProbeAt or 0)) > (Config.KnowProbeGap or 8) then
            Bot.KnowProbePending = { name = entry.name, state = state }
            return true, p, nil
        end
        return false, p, string.format("%.0f%% to land on a %s target", p * 100, state)
    end
    -- something that deals nothing and only drags the target in is pointless
    -- once the target is already at arm's length
    if f and f.nd and kind == "pull" and (d2d or 99) < (Config.KnowPullMin or 12) then
        return false, p, "pull with the target already here"
    end
    -- a move that goes off around us, or at arm's length, after a wind-up:
    -- will the target still be inside it when it does?
    if (kind == "aoe_self" or kind == "melee" or kind == "grab") and state ~= "stun" and state ~= "rag" then
        local _, hi = moveRange(entry)
        local mean, windup = knowTiming(entry.name)
        local wait = windup or mean or 0.25
        local pp, h = tacPredict(t, wait), getHRP()
        if pp and h and hi then
            local dd = Vector3.new(pp.X - h.Position.X, 0, pp.Z - h.Position.Z).Magnitude
            if dd > hi + (Config.KnowReachSlack or 3) and dd > (d2d or 0) then
                return false, p, string.format("leaving: %.0f studs off when it lands (reach %.0f)", dd, hi)
            end
        end
    end
    return true, p, nil
end

-- Called by every chooser. Keeps the count of what was withheld and why.
function knowGate(entry, t, d2d, ctx)
    local ok, p, why = knowAllows(entry, t, d2d, ctx)
    if not ok then
        local now = tick()
        if now - (Know.heldAt[entry.name] or 0) > 1.5 then
            Know.heldAt[entry.name] = now
            Life.knowHeld = (Life.knowHeld or 0) + 1
            if type(Life.knowWhy) ~= "table" then Life.knowWhy = {} end
            local st = (why and why:match("on a (%a+) target")) or (why and why:match("^(%a+)")) or "?"
            Life.knowWhy[st] = (Life.knowWhy[st] or 0) + 1
            debugEvery("know:" .. tostring(entry.name), 8, "held: " .. tostring(entry.name) .. " - " .. tostring(why))
        end
    end
    return ok, p
end

-- How much to favour a move for the state the target is in.
function knowWeight(entry, t)
    if not Config.Know or not entry or not t then return 1 end
    local kind, f = knowKind(entry.name, entry.rule)
    if Know.PASSIVE[kind] then return 1 end
    local p = knowChance(entry.name, knowState(t), kind, f)
    return math.clamp(p / 0.35, 0.3, 2.4)
end

-- Does this move leave the target standing (the string goes on) or put it
-- on the ground (the string is over)? What was seen first, then research.
function knowRole(name)
    local f = MoveFacts[senseMoveKey(name)]
    local o = type(MEM.facts) == "table" and MEM.facts[name] or nil
    if o and (o.hn or 0) >= 4 then
        if (o.rg or 0) / o.hn >= 0.6 then return "ender" end
        if (o.st or 0) / o.hn >= 0.6 then return "extender" end
    end
    return f and f.c or nil
end

-- ------------------------------------------------------------------ probing
-- Every cast is an experiment. memRecordUse notes what the target was doing
-- and where everybody stood; knowWatch follows the next two seconds;
-- knowBook writes down what happened.
function knowStamp(p, t)
    if not Config.Know or not p then return end
    local h, th = getHRP(), getHRP(t)
    p.ts = knowState(t)
    p.myPos = h and h.Position or nil
    Bot.KnowLastPending = p
    if Bot.KnowHoldName == p.move then p.holdArm = Bot.KnowHoldArm end
    Bot.KnowHoldName = nil
    p.tDist = p.dist
    -- our own basic attack still in flight would be booked as this move's hit
    p.dirty = ((tick() - (Tac.m1StepAt or 0)) < 0.45 and Bot.M1Active) and true or false
    -- a counter answers whoever swung, who need not be our target
    if p.ctx == "counter" then
        p.ts, p.dirty = "swing", false
        local vs = Bot.KnowCastVs
        if vs and vs ~= t and vs.Parent then p.target, p.hp0, p.key = vs, getHP(vs), nil end
    end
    local probe = Bot.KnowProbePending
    if probe and probe.name == p.move then
        p.probe = true
        Bot.KnowProbeAt = tick()
        Life.knowProbes = (Life.knowProbes or 0) + 1
        debug(string.format("probe: %s at a %s target (not known whether it lands)", tostring(p.move), tostring(p.ts)))
    end
    Bot.KnowProbePending = nil
end

function knowWatch(p, el)
    local t = p.target
    if not (t and t.Parent) or el > 2.6 or not p.ts then return end
    local hp = getHP(t)
    if p.dirty and not p.kBase and el >= 0.22 then p.kBase = hp end
    local base = p.kBase or ((not p.dirty) and p.hp0) or nil
    if not p.hitAt then
        if hp and base and (base - hp) > 0.5 then
            p.hitAt = el
            local th = getHRP(t)
            p.hitPos = th and th.Position or nil
        end
    elseif not p.after and (el - p.hitAt) >= 0.3 then
        p.after = isRagdolled(t) and "rag" or (isStunned(t) and "stun" or "none")
        local th = getHRP(t)
        if th and p.hitPos then p.knock = (th.Position - p.hitPos).Magnitude end
    end
    -- a move that deals nothing is judged by what it does to the target
    if not p.fx and el > 0.15 and el < 1.6 and p.ts ~= "stun" and p.ts ~= "rag"
       and (isStunned(t) or isRagdolled(t)) then
        p.fx = el
    end
    if el <= 0.9 and p.myPos then
        local h = getHRP()
        if h then
            local dd = Vector3.new(h.Position.X - p.myPos.X, 0, h.Position.Z - p.myPos.Z).Magnitude
            if dd > (p.moved or 0) then p.moved = dd end
        end
    end
end

function knowBook(p, hp1)
    if not Config.Know or not p or not p.move or not p.ts or p.kDone then return end
    p.kDone = true
    if not Know.seeded then knowSeed() end
    if type(MEM.facts) ~= "table" then MEM.facts = {} end
    local o = MEM.facts[p.move]
    if not o then o = { n = 0, s = {} }; MEM.facts[p.move] = o end
    if type(o.s) ~= "table" then o.s = {} end
    local f = MoveFacts[senseMoveKey(p.move)]
    local base = p.kBase or p.hp0
    local dmg = (base or 0) - (hp1 or 0)
    local hit = (p.hitAt ~= nil and dmg > 0.5) or ((f and f.nd and p.fx ~= nil) and true or false)
    local st = p.ts
    local c = o.s[st]
    if not c then c = { n = 0, h = 0 }; o.s[st] = c end
    o.n = (o.n or 0) + 1
    c.n = c.n + 1
    if hit then
        c.h = c.h + 1
        o.hn = (o.hn or 0) + 1
        if p.after == "rag" then o.rg = (o.rg or 0) + 1
        elseif p.after == "stun" then o.st = (o.st or 0) + 1 end
        if p.knock then o.kb = (o.kb or 0) + p.knock end
        -- wind-up and speed: only from casts with no basic attack in flight
        -- at a target that was not already being hit
        if p.hitAt and not p.dirty and p.dist and st ~= "stun" and p.hitAt < 2.5 then
            o.rn = (o.rn or 0) + 1
            o.rd = (o.rd or 0) + p.dist
            o.rt = (o.rt or 0) + p.hitAt
            o.rdd = (o.rdd or 0) + p.dist * p.dist
            o.rdt = (o.rdt or 0) + p.dist * p.hitAt
        end
    end
    if p.moved then o.mv = (o.mv or 0) + p.moved; o.mvN = (o.mvN or 0) + 1 end
    if p.holdArm and type(o.hold) == "table" and type(o.hold[p.holdArm]) == "table" then
        local arm = o.hold[p.holdArm]
        arm.n = arm.n + 1
        arm.d = arm.d + math.max(dmg, 0)
    end
    if p.p2arm and type(o.p2) == "table" and type(o.p2[p.p2arm]) == "table" then
        local arm = o.p2[p.p2arm]
        arm.n = arm.n + 1
        arm.d = arm.d + math.max(dmg, 0)
    end
    if type(Life.know) ~= "table" then Life.know = {} end
    local l = Life.know[p.move]
    if not l then l = { n = 0, h = 0 }; Life.know[p.move] = l end
    l.n = l.n + 1
    if hit then l.h = l.h + 1 end
    if p.probe then
        debug(string.format("probe result: %s at a %s target %s", tostring(p.move), st,
            hit and string.format("landed (%.0f dmg, %.2f s after the cast)", dmg, p.hitAt or p.fx or 0) or "did not land"))
    end
    -- research that the measurements contradict is worth a line: either the
    -- research is wrong or the game has changed
    if f and st == "block" and f.ub == false and c.n >= 4 and c.h / c.n >= 0.6 and not c.said then
        c.said = true
        debug(string.format("research check: %s is listed as blockable but landed %d of %d on blocking targets", p.move, c.h, c.n))
    elseif f and st == "block" and f.ub == true and c.n >= 5 and c.h == 0 and not c.said then
        c.said = true
        debug(string.format("research check: %s is listed as getting through a block but landed 0 of %d", p.move, c.n))
    elseif f and st == "rag" and f.rag == true and c.n >= 5 and c.h == 0 and not c.said then
        c.said = true
        debug(string.format("research check: %s is listed as hitting a body on the ground but landed 0 of %d", p.move, c.n))
    end
end

function knowNoteCooldown(name, cd)
    if not Config.Know or type(cd) ~= "number" or cd < 0.3 or cd > 400 then return end
    if type(MEM.facts) ~= "table" then MEM.facts = {} end
    local o = MEM.facts[name]
    if not o then o = { n = 0, s = {} }; MEM.facts[name] = o end
    o.cd = o.cd and (o.cd * 0.7 + cd * 0.3) or cd
end

-- A cast is taken as refused when its cooldown has not started 0.4 s later.
-- Some moves only start it when they finish (two-press and held moves), so
-- a refused cast is looked at once more: if the cooldown moved after all,
-- the move was never refused, and from the second time on it is given
-- longer before it is judged. A wrongly refused cast was also rolled back
-- out of the books, which is why such moves looked like they never landed.
function knowVerifyDelay(name)
    local o = type(MEM.facts) == "table" and MEM.facts[name] or nil
    local spec = Config.Know and Config.KnowSecondPress and type(Know.P2) == "table" and Know.P2[senseMoveKey(name)] or nil
    if spec then return spec.verify or 1.4 end
    if Bot.HoldCastName == name and tick() < (Bot.HoldCastUntil or 0) then
        return (Bot.HoldCastUntil - tick()) + 1.2      -- a held cast starts its cooldown when it is let go
    end
    if Config.Know and o and (o.late or 0) >= 2 then return Config.KnowLateVerify or 1.3 end
    return Config.CastVerifyDelay or 0.4
end

function knowLateStamp(name, service)
    if not Config.Know then return end
    if type(MEM.facts) ~= "table" then MEM.facts = {} end
    local o = MEM.facts[name]
    if not o then o = { n = 0, s = {} }; MEM.facts[name] = o end
    o.late = (o.late or 0) + 1
    Life.lateStamp = (Life.lateStamp or 0) + 1
    if Bot.Refused then Bot.Refused[service] = 0 end
    if Bot.RefusedN then Bot.RefusedN[service] = 0 end
    debugEvery("late:" .. tostring(name), 4, string.format("not refused after all: %s started its cooldown late (seen %d times%s)",
        tostring(name), o.late, o.late >= 2 and ", now given longer before it is judged" or ""))
end

-- One line per move used this life: what it is, who says so, what it did.
function knowLifeReport()
    if not Config.Know or type(Life.know) ~= "table" then return end
    local names = {}
    for name in pairs(Life.know) do table.insert(names, name) end
    table.sort(names)
    for _, name in ipairs(names) do
        local l = Life.know[name]
        local kind, f, src = knowKind(name)
        local o = (type(MEM.facts) == "table" and MEM.facts[name]) or {}
        local parts = {}
        for _, st in ipairs(Know.STATES) do
            local c = type(o.s) == "table" and o.s[st] or nil
            if c and c.n > 0 then table.insert(parts, string.format("%s %.0f/%.0f", st, c.h, c.n)) end
        end
        local mean, windup, speed = knowTiming(name)
        local extra = ""
        if mean then extra = extra .. string.format(" | lands %.2f s after the cast", mean) end
        if windup and speed then extra = extra .. string.format(" (wind-up %.2f s, %.0f studs/s)", windup, speed) end
        if o.cd then
            extra = extra .. string.format(" | cooldown %.1f s%s", o.cd, (f and f.cd) and string.format(" (listed %s)", tostring(f.cd)) or "")
        end
        if (o.mvN or 0) > 0 then extra = extra .. string.format(" | carries us %.0f studs", (o.mv or 0) / o.mvN) end
        if (o.hn or 0) > 0 then
            extra = extra .. string.format(" | after a hit: down %d, held %d of %d", o.rg or 0, o.st or 0, o.hn)
        end
        if type(o.hold) == "table" and ((o.hold.tap and o.hold.tap.n or 0) + (o.hold.hold and o.hold.hold.n or 0)) > 0 then
            local tp, hd = o.hold.tap or { n = 0, d = 0 }, o.hold.hold or { n = 0, d = 0 }
            extra = extra .. string.format(" | tapped %.1f dmg x%d, held %.1f dmg x%d",
                tp.n > 0 and tp.d / tp.n or 0, tp.n, hd.n > 0 and hd.d / hd.n or 0, hd.n)
        end
        local spec2 = type(Know.P2) == "table" and Know.P2[senseMoveKey(name)] or nil
        if spec2 and type(o.p2) == "table" then
            local arms = {}
            for i, dl in ipairs(spec2.delays) do
                local a = o.p2[i]
                if type(a) == "table" and a.n > 0 then arms[#arms + 1] = string.format("%.2f s: %.1f dmg x%d", dl, a.d / a.n, a.n) end
            end
            if #arms > 0 then extra = extra .. " | second press at " .. table.concat(arms, ", ") end
        end
        debug(string.format("KNOW %s: %s (%s%s%s) | this life %d/%d | career %s%s",
            name, kind, src,
            (f and f.ub ~= nil) and (f.ub and ", unblockable" or ", blockable") or "",
            (f and f.rag ~= nil) and (f.rag and ", hits the ground" or ", misses the ground") or "",
            l.h, l.n, (#parts > 0) and table.concat(parts, ", ") or "nothing booked", extra))
    end
end

function knowLifeSummary()
    local top, topN = "-", 0
    for k, v in pairs(Life.knowWhy or {}) do
        if v > topN then top, topN = k, v end
    end
    local fin = {}
    for _, m in ipairs({ "down", "up", "flat" }) do
        local r = type(Life.fin) == "table" and Life.fin[m] or nil
        if r and r.n > 0 then table.insert(fin, string.format("%s x%d (net %+.0f)", m, r.n, r.net)) end
    end
    return string.format(" | knowledge: %d casts withheld (mostly %s x%d), %d probes, %d counters, %d guard-breaks, %d ground hits, M1 held off %.0fs, finishers %s, %d refusals that were not, second presses %d of %d (%d lost to a stun)",
        Life.knowHeld or 0, top, topN, Life.knowProbes or 0, Life.knowCounter or 0, Life.knowBreak or 0,
        Life.knowGround or 0, Life.m1HeldSec or 0, (#fin > 0) and table.concat(fin, ", ") or "none", Life.lateStamp or 0,
        Life.p2Sent or 0, Life.p2Cast or 0, Life.p2Lost or 0)
end

-- ------------------------------------------------------------------ the fourth hit
-- A basic string is four hits. The fourth puts the target down, and which
-- fourth comes out depends on what our feet are doing: on the ground it
-- knocks them away, rising it launches them (the longest time down),
-- falling it slams them where they stand, cannot be blocked and reaches a
-- body already on the ground. Which of those pays best is not something a
-- guide can say for every moveset, so each is tried a few times and the
-- damage dealt minus the damage taken over the next four seconds is kept.
function tacFinisherPick(t)
    local mode = Config.TacFinisher or "auto"
    if mode ~= "auto" then return mode end
    if t and knowBlocking(t) then return "down" end      -- the only fourth that beats a guard
    local fin = type(MEM.tactics) == "table" and MEM.tactics.fin or nil
    local best, bestV, least, leastN = "down", -math.huge, nil, math.huge
    for _, m in ipairs({ "down", "up", "flat" }) do
        local r = type(fin) == "table" and fin[m] or nil
        local n = r and r.n or 0
        if n < (Config.TacFinisherTrials or 4) and n < leastN then least, leastN = m, n end
        if n > 0 and r.net / n > bestV then best, bestV = m, r.net / n end
    end
    return least or best
end

-- Called from the basic-attack loop. Returns "hold" while the swing has to
-- wait. The game's own client sends "Down" for a swing thrown in the air and
-- "Up" for one thrown from the ground with jump held, so the two are timed
-- differently: for the slam we jump early and swing once airborne; for the
-- launcher we wait until the swing is due and jump on the same frame.
function tacFinisher()
    local mode = Config.TacFinisher
    if not mode or mode == "off" then return nil end
    local me, hum, t = getChar(), getHum(), Bot.Target
    local now = tick()
    local len, variants = tacStringLen()
    if not variants then return nil end                 -- this character's last hit comes one way only
    if not (me and hum and t) or me:GetAttribute("CurrentM1") ~= len then   -- the last hit of the string is next
        if Bot.FinMode and (now - (Bot.FinAt or 0)) > 1.5 then Bot.FinMode = nil end
        return nil
    end
    if not (isStunned(t) or knowBlocking(t)) or isRagdolled(t) then return nil end
    local since = now - (Tac.m1StepAt or 0)
    -- the chained skill gets first refusal on this moment
    if since < (Config.TacComboDelay or 0.14) + 0.05 then return nil end
    if not Bot.FinMode then Bot.FinMode, Bot.FinAt = tacFinisherPick(t), now end
    local gap = Tac.m1Gap or 0.35
    if Bot.FinMode == "up" then
        if since < gap - 0.04 and (now - Bot.FinAt) < 0.4 then return "hold" end
        hum.Jump = true
        Bot.M1DirForce, Bot.M1DirForceUntil = "Up", now + 0.3
        Bot.FinGot = "up"
        return nil
    elseif Bot.FinMode == "down" then
        if hum.FloorMaterial == Enum.Material.Air then Bot.FinGot = "down" return nil end
        -- never left the ground (the game locks the jump in some states):
        -- swing anyway, and book it as the flat hit it will be
        if (now - Bot.FinAt) > 0.3 then Bot.FinGot = "flat" return nil end
        if since >= math.max(0.19, gap - 0.15) then hum.Jump = true end
        return "hold"
    end
    Bot.FinGot = "flat"
    return nil
end

-- The step counter going from 4 to 5 means the fourth hit was thrown.
function tacFinisherStep(prev, step)
    local now = tick()
    if type(prev) == "number" and type(step) == "number" and step == prev + 1 and prev >= 2 then
        local g = now - (Tac.m1StepAt or now)
        if g > 0.1 and g < 0.9 then Tac.m1Gap = Tac.m1Gap and (Tac.m1Gap * 0.7 + g * 0.3) or g end
    end
    local len = tacStringLen()
    if prev == len and step == len + 1 and Bot.FinMode and (now - (Bot.FinAt or 0)) < 1.5 then
        Bot.FinPending = { mode = Bot.FinGot or Bot.FinMode, at = now, d0 = Life.dmg or 0, t0 = Life.taken or 0 }
    end
    if prev == len then Bot.FinMode, Bot.FinGot = nil, nil end
end

function tacFinisherBook()
    local fp = Bot.FinPending
    if not fp or (tick() - fp.at) < (Config.TacFinisherWindow or 4) then return end
    Bot.FinPending = nil
    local net = ((Life.dmg or 0) - fp.d0) - ((Life.taken or 0) - fp.t0)
    if type(MEM.tactics) ~= "table" then MEM.tactics = {} end
    if type(MEM.tactics.fin) ~= "table" then MEM.tactics.fin = {} end
    if type(Life.fin) ~= "table" then Life.fin = {} end
    for _, tbl in ipairs({ MEM.tactics.fin, Life.fin }) do
        local r = tbl[fp.mode]
        if not r then r = { n = 0, net = 0 }; tbl[fp.mode] = r end
        r.n = r.n + 1
        r.net = r.net + net
    end
    debugEvery("finisher", 1, string.format("finisher: %s paid %+.0f over the next %.0f s", fp.mode, net, Config.TacFinisherWindow or 4))
end


-- ============================================================================
--  FIGHT SENSE (v89) -- how hits get in, and the moments that decide a fight
--
--  The v86 log says where the stun time comes from: 47% basic attacks, 12%
--  front-dash punches, 18% unidentified, 7% our own recovery after a cast.
--  It does not say what we were doing when each of those landed, and that
--  is the thing to fix next. So every hit that stuns us is written down
--  with what we were doing at the time (the ledger), and three rules from
--  the research are applied to the moments around a knockdown.
-- ============================================================================

-- What we were doing when a hit got through. One word per hit, counted per
-- life and for the career; the life's line names the worst three.
function tacOpener(who, key)
    if not Config.TacLedger or type(key) ~= "string" then return end
    if key:find("^self:") or key:find("^FF:") then return end
    local now = tick()
    local h, wh = getHRP(), who and getHRP(who)
    local st = Tac.lastState or Bot.State or "?"
    local dist, side = nil, "?"
    if h and wh then
        local to = wh.Position - h.Position
        local flat = Vector3.new(to.X, 0, to.Z)
        dist = flat.Magnitude
        if dist > 0.1 then
            local look = h.CFrame.LookVector
            -- a guard covers 170 degrees in front: cos(85) = 0.087
            side = ((flat / dist):Dot(Vector3.new(look.X, 0, look.Z)) >= 0.087) and "front" or "behind"
        end
    end
    local melee = key:find(":Melee%d") ~= nil or key:find(":Hit%d") ~= nil or key:find(":Down$") ~= nil or key:find(":Up$") ~= nil
    local doing
    if Bot.BlockActive then
        doing = (side == "behind") and "block up, hit from behind" or "through a raised block"
    elseif (now - (Tac.selfWokeAt or 0)) < 0.6 then
        doing = "just got up"
        -- the research says half a second of immunity to melee stun on getting up
        if melee and (now - (Tac.selfWokeAt or 0)) < (Config.TacWakeWindow or 0.5) then
            Life.wakeStunned = (Life.wakeStunned or 0) + 1
            debugEvery("wakecheck", 5, string.format("research check: stunned by a basic attack %.2f s after getting up (listed as immune for 0.5 s)",
                now - (Tac.selfWokeAt or 0)))
        end
    elseif (now - (Life.lastUsedAt or 0)) < 1.2 then
        doing = "after a cast"
    elseif (now - (Tac.m1StepAt or 0)) < 0.5 and st == "ATTACK" then
        doing = "mid-swing"
    elseif (now - (Bot.BlockReleasedAt or 0)) < 0.35 then
        doing = "block just dropped"
    elseif st == "APPROACH" or st == "APPROACH_FAR" or st == "CHASE" or st == "FLANK" then
        doing = "closing in"
    elseif st == "RETREAT" or st == "TEAMKITE" then
        doing = "backing off"
    elseif st == "ATTACK" then
        doing = "in reach, not swinging"
    else
        doing = "standing (" .. tostring(st) .. ")"
    end
    if type(Life.open) ~= "table" then Life.open = {} end
    Life.open[doing] = (Life.open[doing] or 0) + 1
    Life.openN = (Life.openN or 0) + 1
    if type(MEM.tactics) ~= "table" then MEM.tactics = {} end
    if type(MEM.tactics.open) ~= "table" then MEM.tactics.open = {} end
    MEM.tactics.open[doing] = (MEM.tactics.open[doing] or 0) + 1
    debugEvery("opener", 0.7, string.format("hit taken: %s from %s studs, %s | we were %s (%s)%s",
        key, dist and string.format("%.0f", dist) or "?", side, doing, tostring(st),
        (now < (Bot.PreGuardRestUntil or 0) and not Bot.BlockActive) and " | a predicted block had just run out" or ""))
end

function tacOpenerSummary()
    local rows = {}
    for k, v in pairs(Life.open or {}) do rows[#rows + 1] = { k = k, v = v } end
    table.sort(rows, function(a, b) if a.v == b.v then return a.k < b.k end return a.v > b.v end)
    local parts = {}
    for i = 1, math.min(4, #rows) do parts[#parts + 1] = string.format("%s %d", rows[i].k, rows[i].v) end
    return string.format(" | hits that got in: %d (%s) | wake-up: swung through %d, guarded theirs %d, stunned while immune %d | held casts %d, awakening waited %.0fs",
        Life.openN or 0, (#parts > 0) and table.concat(parts, ", ") or "none",
        Life.wakeSwing or 0, Life.wakeGuard or 0, Life.wakeStunned or 0, Life.holdCasts or 0, Life.ultWaited or 0)
end

-- Getting up. The research: a player who gets up from a knockdown cannot be
-- stunned by melee for about half a second. Two consequences.
--   Ours:   for that half second their basic attacks do not stop ours, so
--           swing instead of blocking.
--   Theirs: for that half second our basic attacks do not stop theirs, so
--           do not swing; expect theirs, block it and take the turn.
function tacSelfTick(now)
    local rg = isRagdolled()
    if Tac.selfRag and not rg then Tac.selfWokeAt, Tac.selfWakeUsed = now, false end
    Tac.selfRag = rg
    local st = Bot.State
    if st and st ~= "CCED" and st ~= "DEAD" then Tac.lastState = st end
    if getUltMeter() < 100 or isAwakened() then
        if Bot.UltFullSince then Life.ultWaited = (Life.ultWaited or 0) + (now - Bot.UltFullSince) end
        Bot.UltFullSince = nil
    end
end

function tacOwnWake(t)
    if not Config.TacWake or not t then return false end
    if (tick() - (Tac.selfWokeAt or 0)) > (Config.TacWakeWindow or 0.5) then return false end
    if (Bot.Dist2D or 99) > (Config.M1Range or 8) + 3 or isRagdolled(t) then return false end
    if not Tac.selfWakeUsed then
        Tac.selfWakeUsed = true
        Life.wakeSwing = (Life.wakeSwing or 0) + 1
        debugEvery("wakeswing", 2, "wake-up: swinging through, their basic attacks cannot stop ours for half a second")
    end
    return true
end

function tacTheirWake(t, d2d, now)
    if not Config.TacWake or not t or Bot.BlockActive then return false end
    if (d2d or 99) > 10 or (now - (Bot.WakeGuardAt or 0)) < 1.5 then return false end
    if type(isTargetFacingUs) == "function" and not isTargetFacingUs(t) then return false end
    Bot.WakeGuardAt = now
    Life.wakeGuard = (Life.wakeGuard or 0) + 1
    debugEvery("wakeguard", 2, string.format("wake-up: %s is getting up at %.0f studs, guarding the first swing", tostring(t.Name), d2d or 0))
    return true
end

-- Awakening heals and cannot be hit during its opening. Spent the moment
-- the bar fills, the heal is wasted on full health. Worth it when hurt, when
-- the target cannot answer, or when the bar has been full long enough that
-- dying with it unspent is the bigger risk.
function tacAwakenWorth(hp)
    if not Config.TacAwaken then return true end
    local now = tick()
    Bot.UltFullSince = Bot.UltFullSince or now
    if (hp or 100) <= (Config.TacAwakenHP or 70) then return true end
    local t = Bot.Target
    if t and (isStunned(t) or isRagdolled(t)) and (Bot.Dist2D or 99) <= 20 then return true end
    if (now - Bot.UltFullSince) >= (Config.TacAwakenHold or 15) then return true end
    return false
end

-- A domain is 1.25 s of hand signs that any hit cancels.
function knowDomainSafe(t, d2d)
    if not t then return true, 1, nil end
    if isStunned(t) or isRagdolled(t) then return true, 1, nil end
    if (d2d or 0) >= (Config.KnowDomainDist or 22) then return true, 1, nil end
    return false, 0, "domain with a free enemy in reach of the hand signs"
end

-- Held versions. The game sends Deactivated when the key is let go, and
-- several moves are a different, stronger move if it is let go late (Ultra
-- Cannon has its own "Albatros" effects for it, Blunt Cut a "Charge"). The
-- bot let go after 0.1 s every time. Holding costs time standing still, so
-- it is only tried with the target at a distance or on the ground, and tap
-- and hold are compared by the damage each has dealt.
Know.HOLD = {
    UltraCannon  = { t = 1.4 },     -- listed: 1.3 s, becomes an unblockable beam that reaches the ground
    BluntCut     = { t = 0.9 },     -- listed: 9 tapped, 14 held
    Earthquake   = { t = 1.0 },     -- listed: 12.5 tapped and blockable, 25 held and unblockable
    GraniteBlast = { t = 0.8 },
}

function knowHoldFor(name, t, d2d)
    Bot.KnowHoldName, Bot.KnowHoldArm = nil, nil
    if not Config.Know or not Config.KnowHold or not name then return nil end
    local spec = Know.HOLD[senseMoveKey(name)]
    if not spec then return nil end
    if type(MEM.facts) ~= "table" then MEM.facts = {} end
    local o = MEM.facts[name]
    if not o then o = { n = 0, s = {} }; MEM.facts[name] = o end
    if type(o.hold) ~= "table" then o.hold = { tap = { n = 0, d = 0 }, hold = { n = 0, d = 0 } } end
    local safe = t ~= nil and ((d2d or 0) >= (Config.KnowHoldDist or 14) or isRagdolled(t))
    local arm = "tap"
    if safe then
        local tp, hd = o.hold.tap, o.hold.hold
        if hd.n < (Config.KnowHoldTrials or 3) then arm = "hold"
        elseif tp.n < (Config.KnowHoldTrials or 3) then arm = "tap"
        elseif hd.d / hd.n > tp.d / tp.n then arm = "hold" end
    end
    Bot.KnowHoldName, Bot.KnowHoldArm = name, arm
    if arm ~= "hold" then return nil end
    Bot.HoldUntil = tick() + spec.t
    Bot.HoldCastName, Bot.HoldCastUntil = name, tick() + spec.t + 0.2
    Life.holdCasts = (Life.holdCasts or 0) + 1
    debugEvery("hold:" .. tostring(name), 2, string.format("holding %s for %.1f s (target %s)", tostring(name), spec.t,
        isRagdolled(t) and "on the ground" or string.format("%.0f studs off", d2d or 0)))
    return spec.t
end


-- ------------------------------------------------------------------ strings and sessions (v91)
-- Not every basic string is four hits. The research lists True Cannon's as
-- three, and Head of the Hei's fourth as having no slam and no launcher.
-- Everything that counts swings asks here how long this character's string
-- is; the second value says whether the last hit has variants at all.
Know.M1LEN = { Ryu = 3 }
Know.NOFIN = { Naoya = true }
function tacStringLen()
    local me = getChar()
    local set = me and me:GetAttribute("Moveset") or nil
    return (set and Know.M1LEN[set]) or 4, not (set and Know.NOFIN[set])
end

-- One line after every life: is this session going better or worse? Kills
-- and deaths, damage dealt for each 1 taken, time stunned, and the life just
-- ended set against the lives before it.
function tacSessionLine()
    local se = Tac.session
    if not se then
        se = { lives = 0, dmg = 0, taken = 0, dur = 0, stunned = 0, k0 = Bot.Kills or 0 }
        Tac.session = se
    end
    local dur = Life.startAt and (tick() - Life.startAt) or 0
    local before = (se.taken > 0) and (se.dmg / se.taken) or nil
    local mine = (Life.dmg or 0) / math.max(1, Life.taken or 0)
    se.lives = se.lives + 1
    se.dmg = se.dmg + (Life.dmg or 0)
    se.taken = se.taken + (Life.taken or 0)
    se.dur = se.dur + dur
    se.stunned = se.stunned + (Life.stunned or 0)
    local trend = "first life of the session"
    if before then
        if mine > before * 1.15 then trend = "this life better than the session before it"
        elseif mine < before * 0.85 then trend = "this life worse than the session before it"
        else trend = "this life about level with the session before it" end
    end
    debug(string.format("SESSION: %d kills, %d lives in %.0f min | dealt %.2f for each 1 taken (this life %.2f) | stunned %.0f%% of the time (this life %.0f%%) | %s",
        (Bot.Kills or 0) - se.k0, se.lives, se.dur / 60, se.dmg / math.max(1, se.taken), mine,
        100 * se.stunned / math.max(1, se.dur), 100 * (Life.stunned or 0) / math.max(1, dur), trend))
end

-- ------------------------------------------------------------------ reach of a basic attack (v91)
-- The bot swung from 11 studs out on the approach. A swing that meets air
-- still moves the string along, so the fourth hit and its two-second lockout
-- were often spent before the target was in reach. How far a basic attack
-- really reaches is not written anywhere, so every swing is booked by the
-- distance it was thrown from and whether damage followed.
Tac.m1Pending = {}
function tacM1Swing(now)
    if not Config.TacM1Probe then return end
    local t = Bot.Target
    if not (t and t.Parent) or not Bot.Dist2D then return end
    table.insert(Tac.m1Pending, { at = now, d = Bot.Dist2D, t = t, hp = getHP(t), st = knowState(t) })
end

function tacM1Resolve(now)
    local list = Tac.m1Pending
    for i = #list, 1, -1 do
        local p = list[i]
        if now - p.at >= 0.4 then
            table.remove(list, i)
            -- a skill of ours in the air would be booked as the swing's damage
            if p.t.Parent and (now - (Bot.LastSkill or 0)) > 1.0 and p.st ~= "block" and p.st ~= "rag" then
                local hit = (p.hp or 0) - (getHP(p.t) or 0) > 0.5
                if type(MEM.tactics) ~= "table" then MEM.tactics = {} end
                if type(MEM.tactics.m1r) ~= "table" then MEM.tactics.m1r = {} end
                local key = tostring(math.min(math.floor(p.d / 2) * 2, 12))
                local b = MEM.tactics.m1r[key]
                if type(b) ~= "table" then b = { n = 0, h = 0 }; MEM.tactics.m1r[key] = b end
                b.n = b.n + 1
                if hit then b.h = b.h + 1 end
            end
        end
    end
end

-- The furthest two-stud band in which swings still land one time in four.
function tacM1Reach()
    local r = type(MEM.tactics) == "table" and MEM.tactics.m1r or nil
    local best = nil
    if Config.TacM1Probe and type(r) == "table" then
        for lo = 0, 12, 2 do
            local b = r[tostring(lo)]
            if type(b) == "table" and b.n >= 8 and b.h / b.n >= 0.25 then best = lo + 2 end
        end
    end
    return best or Config.M1Range or 7, best ~= nil
end

function tacM1InReach(t, d2d)
    if not t or not d2d then return false end
    local reach = (tacM1Reach()) + (Config.TacM1Slack or 1.0)
    if d2d <= reach then return true end
    if d2d > reach + 5 then return false end
    -- closing: will the gap be shut by the time the swing comes out?
    local h, th = getHRP(), getHRP(t)
    if not (h and th) then return false end
    local to = Vector3.new(th.Position.X - h.Position.X, 0, th.Position.Z - h.Position.Z)
    if to.Magnitude < 0.1 then return true end
    local dir = to.Unit
    local own = h.AssemblyLinearVelocity
    local closing = (own and Vector3.new(own.X, 0, own.Z):Dot(dir) or 0) - tacVelocity(t):Dot(dir)
    return d2d - closing * (Config.TacM1Lead or 0.2) <= reach
end

function tacM1ReachSummary()
    local r = type(MEM.tactics) == "table" and MEM.tactics.m1r or nil
    local parts = {}
    if type(r) == "table" then
        for lo = 0, 12, 2 do
            local b = r[tostring(lo)]
            if type(b) == "table" and b.n > 0 then
                parts[#parts + 1] = string.format("%s %d/%d", lo >= 12 and "12+" or string.format("%d-%d", lo, lo + 2), b.h, b.n)
            end
        end
    end
    local reach, learned = tacM1Reach()
    return string.format(" | swings by distance: %s; reach taken as %.0f studs%s | casts turned onto the target %d of %d",
        (#parts > 0) and table.concat(parts, ", ") or "none yet", reach, learned and " (measured)" or " (default)",
        Life.castTurned or 0, Life.castFaced or 0)
end

-- ------------------------------------------------------------------ openers (v90)
-- The front-dash punch: a 20-stud slide into a jab that stuns, on a 6 s
-- cooldown. It is 12% of the stuns we take and it is how opponents start
-- their strings on us. The bot only used it to run down somebody fleeing.
-- Now it opens with it: from far enough that the punch stuns (inside half
-- the slide it knocks down instead, and a knockdown starts nothing), and
-- not into a guard, which costs us extra recovery.
function tacDashOpen(t, d2d, now)
    if not Config.TacDashOpen or not t or not d2d then return false end
    if d2d < (Config.TacDashMin or 11) or d2d > (Config.TacDashMax or 18) then return false end
    if now - (Bot.LastChase or 0) < (Config.TacDashCooldown or 6.2) then return false end
    if math.abs(Bot.DistY or 0) > 5 then return false end
    local st = knowState(t)
    if st == "block" or st == "rag" or st == "wake" or st == "air" then return false end
    if hasIFrames(t) then return false end
    return true
end

function tacDashOpened(t, now)
    Bot.DashOpen = { t = t, at = now }
    Life.dashOpen = (Life.dashOpen or 0) + 1
    debugEvery("dashopen", 1.5, string.format("opening with a dash punch from %.0f studs", Bot.Dist2D or 0))
end

-- Did it land? The target is stunned and beside us within a second.
function tacDashOpenTick(now)
    local d = Bot.DashOpen
    if not d then return end
    local el = now - d.at
    local t = d.t
    if not (t and t.Parent) or el > 1.1 then Bot.DashOpen = nil return end
    if el < 0.2 then return end
    local h, th = getHRP(), getHRP(t)
    if h and th and isStunned(t) and not isRagdolled(t)
       and Vector3.new(th.Position.X - h.Position.X, 0, th.Position.Z - h.Position.Z).Magnitude <= 9 then
        Life.dashOpenHit = (Life.dashOpenHit or 0) + 1
        if type(MEM.tactics) ~= "table" then MEM.tactics = {} end
        MEM.tactics.dashHit = (MEM.tactics.dashHit or 0) + 1
        Bot.DashOpen = nil
    end
end

-- Escaping a knockdown straight backwards leaves us on the line of their
-- next dash. Step out to the side instead, and of the two sides take the
-- one that leads back toward the middle of the arena, not into a wall.
function tacEscapeDir(h, from, fallback)
    if not Config.TacEscapeSide or not (h and from) then return fallback end
    local away = Vector3.new(h.Position.X - from.Position.X, 0, h.Position.Z - from.Position.Z)
    if away.Magnitude < 0.1 then return fallback end
    away = away.Unit
    local left = Vector3.new(-away.Z, 0, away.X)
    local pick = left
    local centre = type(mapArenaCentre) == "function" and mapArenaCentre() or nil
    if centre then
        local toC = Vector3.new(centre.X - h.Position.X, 0, centre.Z - h.Position.Z)
        if toC.Magnitude > 1 and toC:Dot(left) < 0 then pick = left * -1 end
    elseif math.random() < 0.5 then
        pick = left * -1
    end
    -- a little away as well as across
    return dashDirFor(pick + away * 0.35)
end

function tacOpenSummary()
    return string.format(" | dash punches %d (%d landed) | took %.0f dmg", Life.dashOpen or 0, Life.dashOpenHit or 0, Life.taken or 0)
end


local function getAimPoint()
    local h = getHRP()
    local t = Bot.Target
    if t then
        local th = getHRP(t)
        if th then
            -- buildExtra sets the lead for the move being cast, a moment before
            if Config.TacLead and (Bot.LeadT or 0) > 0 and (tick() - (Bot.LeadAt or 0)) < 0.2 then
                return tacPredict(t, Bot.LeadT) or th.Position
            end
            return th.Position
        end
    end
    return h and (h.Position + h.CFrame.LookVector * 40) or Vector3.zero
end

local function buildExtra(moveName)
    local rule = MoveRules[moveName] or DefaultRule
    local code = rule.code or 0
    Bot.LeadT, Bot.LeadAt = tacLeadTime(moveName, Bot.Dist2D), tick()

    if code == 1 then return isAirborne() end
    if code == 2 then return Bot.Target end
    if code == 3 then return getAimPoint() end
    if code == 4 then return getMoveVector() end
    if code == 5 then
        return { isAirborne(), Bot.Target, getAimPoint(), getMoveVector() }
    end
    if code == 6 then
        local i = getInfo()
        return { isAirborne(), i ~= nil and i:FindFirstChild("InDash") ~= nil,
                 i ~= nil and i:FindFirstChild("InRoll") ~= nil }
    end
    if code == 7 then
        -- 1.85 (Turbulence): airborne, or the jump key is down right now
        local hum = getHum()
        return isAirborne() or (hum ~= nil and hum.Jump == true)
    end
    return false
end
















local m1Thread = nil
local lastM1Log = 0

local function m1Direction()
    local hum = getHum()
    if not hum then return nil end
    if Bot.M1DirForce and tick() < (Bot.M1DirForceUntil or 0) then return Bot.M1DirForce end

    local c = getChar()
    local set = c and c:GetAttribute("Moveset")
    local airborne = hum.FloorMaterial == Enum.Material.Air
    local jumping = hum.Jump

    if set == "Hanami" then

        if jumping then return "Up" end
        if airborne then return "Down" end
        return nil
    end

    if airborne then return "Down" end
    if jumping then return "Up" end
    return nil
end



local function fireM1Once(dryRun)
    local c = getChar()
    if not c then return "no-char" end

    local dir = m1Direction()
    local target = Bot.Target


    local crow = rawget(_G, "Crow")
    if crow and typeof(crow) == "Instance" then
        if dryRun then return "crow" end
        local ok = pcall(function() crow:FireServer(true) end)
        if ok then return "crow" end
    end

    local info = getInfo(c)


    local item = info and info:FindFirstChild("Item")
    if item and item:FindFirstChild("M1") then
        if dryRun then return "item" end
        if fireRemote("ItemService", "M1", dir, target) then return "item" end
    end











    if info and info:FindFirstChild("DomainClash") then
        if dryRun then return "domainclash" end
        if fireRemote("DomainService", "Activated", dir) then return "domainclash" end
    end


    if c:FindFirstChild("CustomM1") or c:GetAttribute("CustomM1") then
        if dryRun then return "custom" end
        if fireRemote("CustomService", "Melee", target) then return "custom" end
    end


    local svc = getMovesetService()
    if not svc then return "no-service" end
    if dryRun then

        return svc .. (getRemote and "" or "") ..
               (getService(svc) and " [resolved]" or " [NO SERVICE]")
    end
    if fireRemote(svc, "Activated", dir, target) then return svc end
    return "FAILED:" .. svc
end















local m1Accum = 0
local m1Fires = 0
local m1LastReport = 0

local function startM1()
    Bot.M1Active = true
end

local function stopM1()
    Bot.M1Active = false
end


local function tickM1(dt)
    if not Bot.M1Active or not Config.Enabled or tick() < (Bot.HoldUntil or 0)
       or (Config.TacBlockKeep and Bot.BlockActive and Bot.BlockHeld) then
        m1Accum = 0
        return
    end

    m1Accum = m1Accum + (dt or 0.016)
    if m1Accum < 0.025 then return end
    m1Accum = 0

    if tacFinisher() == "hold" then return end
    local ok, res = pcall(fireM1Once)
    if ok then
        m1Fires = m1Fires + 1
        Bot.LastOffense = tick()
        if Config.DebugM1 and tick() - m1LastReport > 1.0 then
            m1LastReport = tick()
            debug(string.format("M1 %d/s branch=%s dir=%s tgt=%s",
                m1Fires, tostring(res), tostring(m1Direction()),
                tostring(Bot.Target and Bot.Target.Name)))
            m1Fires = 0
        end
    else

        if tick() - m1LastReport > 1.0 then
            m1LastReport = tick()
            debug("M1 ERROR (recovering): " .. tostring(res))
        end
    end
end


local function useSkill(serviceName)
    local moves = getAvailableMoves()
    local m = moves[serviceName]
    if not m then return false end
    -- A cast thrown while we cannot act is refused by the server and still
    -- costs the decision; 19% of all casts were refused. Stun and ragdoll
    -- are certain refusals. Whether blocking is one is not known (casts
    -- straight out of a block were accepted in the logs), so the block state
    -- goes into the refusal line instead of into the gate.
    if tick() < (Bot.HoldUntil or 0) then return false end
    if Config.TacCastGate and not (MoveRules[m.value.Name] or DefaultRule).escape then
        if isStunned() or isRagdolled() then
            Life.tacGated = (Life.tacGated or 0) + 1
            return false
        end
        -- the fourth swing has just gone out: the server refuses a cast for a
        -- moment after it
        local meG = getChar()
        if meG and meG:GetAttribute("CurrentM1") == (tacStringLen()) + 1
           and (tick() - (Tac.m1StepAt or 0)) < (Config.TacAfterFourth or 0.35) then
            Life.tacGated = (Life.tacGated or 0) + 1
            return false
        end
    end
    if Config.TacBlockKeep and Bot.BlockActive and Bot.BlockHeld
       and (tick() - (Bot.BlockSince or 0)) < (Config.TacBlockMin or 0.3)
       and not (MoveRules[m.value.Name] or DefaultRule).escape then
        return false
    end



    if Bot.Refused and (tick() - (Bot.Refused[serviceName] or 0)) < (Config.CastRefusalHold or 2.5) then return false end

    local moveValue = m.value



    if Config.BlankSlotSkip and moveValue.Name == "-" then
        Life.blankSaid = Life.blankSaid or {}
        if not Life.blankSaid[serviceName] then
            Life.blankSaid[serviceName] = true
            debug("slot blank: " .. tostring(serviceName))
        end
        return false
    end
















    if type(allyInBlast) == "function" and allyInBlast(moveValue.Name, serviceName) then
        return false
    end

    stopM1()
    -- Lead: anything that has to cross a gap is thrown at where the target
    -- is heading. Moves aimed by the body are turned; moves aimed by a point
    -- get the point from getAimPoint through buildExtra.
    if Config.TacLead and Bot.Target then
        local ruleL = MoveRules[moveValue.Name] or DefaultRule
        local leadL = tacLeadTime(moveValue.Name, Bot.Dist2D)
        if leadL > 0 and (ruleL.max or 0) >= 25 then
            local pp, hL = tacPredict(Bot.Target, leadL), getHRP()
            local thL = getHRP(Bot.Target)
            if pp and hL and thL and (pp - thL.Position).Magnitude > 1.5 then
                local flat = Vector3.new(pp.X, hL.Position.Y, pp.Z)
                if (flat - hL.Position).Magnitude > 2 then
                    pcall(function() hL.CFrame = CFrame.lookAt(hL.Position, flat) end)
                    Bot.FaceLeadUntil = tick() + 0.35
                    Life.tacLead = (Life.tacLead or 0) + 1
                end
            end
        end
    end
    -- Face what is being thrown at. Since v86 the body follows the feet while
    -- covering ground; without this a cast on the approach leaves along the
    -- path. The turn is instant, and the body then stays on the target
    -- through the wind-up instead of swinging back to the path.
    if Config.TacFaceCast and Bot.Target then
        local hF, thF = getHRP(), getHRP(Bot.Target)
        if hF and thF then
            local flat = Vector3.new(thF.Position.X, hF.Position.Y, thF.Position.Z)
            local to = flat - hF.Position
            if to.Magnitude > 1 then
                Life.castFaced = (Life.castFaced or 0) + 1
                if hF.CFrame.LookVector:Dot(to.Unit) < 0.87 then Life.castTurned = (Life.castTurned or 0) + 1 end
                if tick() >= (Bot.FaceLeadUntil or 0) then
                    pcall(function() hF.CFrame = CFrame.lookAt(hF.Position, flat) end)
                end
            end
            Bot.FaceCastUntil = tick() + (Config.TacFaceCastHold or 0.6)
        end
    end
    local castInfo = string.format("m1=%s dash=%s blk=%s/%.2f tstun=%s trag=%s d=%.0f ctx=%s",
        tostring(getChar() and getChar():GetAttribute("CurrentM1")),
        tostring(getInfo() ~= nil and getInfo():FindFirstChild("InDash") ~= nil),
        tostring(Bot.BlockActive and true or false), math.min(tick() - (Bot.BlockReleasedAt or 0), 9.99),
        tostring(Bot.Target ~= nil and isStunned(Bot.Target)),
        tostring(Bot.Target ~= nil and isRagdolled(Bot.Target)),
        Bot.Dist2D or -1,
        tostring((Bot.CastCtx and (tick() - (Bot.CastCtxAt or 0)) < 0.15) and Bot.CastCtx or "neutral"))
    local extra = buildExtra(moveValue.Name)
    fireRemote(serviceName, "Activated", moveValue, extra)
    -- let go late where the held version is the better move (see Know.HOLD)
    local holdFor = knowHoldFor(moveValue.Name, Bot.Target, Bot.Dist2D)
    task.delay(holdFor or 0.1, function()
        fireRemote(serviceName, "Deactivated", moveValue, extra)
    end)

    Bot.LastSkill = tick()
    local offenseBefore = Bot.LastOffense
    Bot.LastOffense = tick()
    local offenseAt = Bot.LastOffense
    Bot.UsedSkillsThisFight[serviceName] = tick()
    Bot.UsedSkillsThisLife = Bot.UsedSkillsThisLife or {}
    Bot.UsedSkillsThisLife[serviceName] = tick()
    local castAt = tick()
    memRecordUse(moveValue.Name, Bot.Target, Bot.Dist2D)
    knowP2Cast(moveValue.Name, serviceName, moveValue)







    Bot.Refused = Bot.Refused or {}
    local verifyIn = knowVerifyDelay(moveValue.Name)
    Bot.Refused[serviceName] = castAt - (Config.CastRefusalHold or 2.5) + verifyIn







    local before, beforeUse = moveValue:GetAttribute("ReadyAt"), moveValue:GetAttribute("LastUse")
    task.delay(verifyIn, function()
        local ok, after, afterUse = pcall(function()
            return moveValue:GetAttribute("ReadyAt"), moveValue:GetAttribute("LastUse")
        end)
        if not ok then return end
        if after == before and afterUse == beforeUse and not inOwnMove() then


            if after == nil and afterUse == nil then
                Bot.NilStamp = Bot.NilStamp or {}
                Bot.NilStamp[serviceName] = (Bot.NilStamp[serviceName] or 0) + 1
                if Bot.NilStamp[serviceName] > 3 then return end
            end
            Bot.Refused = Bot.Refused or {}
            Bot.RefusedN = Bot.RefusedN or {}
            local nRef = (Bot.RefusedN[serviceName] or 0) + 1
            Bot.RefusedN[serviceName] = nRef
            -- A move refused again and again is waiting on something we cannot
            -- see (a summon already out, a resource, a stance). Each refusal
            -- in a row doubles how long it is left alone, up to eight times.
            Bot.Refused[serviceName] = tick() + (math.min(2 ^ (nRef - 1), 8) - 1) * (Config.CastRefusalHold or 2.5)
            Life.refused = (Life.refused or 0) + 1
            -- some moves start their cooldown only when they finish: look once more
            task.delay(0.9, function()
                local ok2, after2, afterUse2 = pcall(function()
                    return moveValue:GetAttribute("ReadyAt"), moveValue:GetAttribute("LastUse")
                end)
                if ok2 and (after2 ~= before or afterUse2 ~= beforeUse) then
                    knowLateStamp(moveValue.Name, serviceName)
                end
            end)




            local _, rolled = memUnrecordUse(moveValue.Name, castAt)
            if Config.CastRollback and Bot.LastOffense == offenseAt then
                Bot.LastOffense = offenseBefore or 0
                rolled = true
            end
            if rolled then Life.unstamped = (Life.unstamped or 0) + 1 end

            if Bot.UsedSkillsThisLife then Bot.UsedSkillsThisLife[serviceName] = nil end
            Bot.UsedSkillsThisFight[serviceName] = nil
            debugEvery("refused:" .. serviceName, 5, "refused: " .. moveValue.Name .. " (no stamp moved | at cast: " .. castInfo .. ")")
        else
            if Bot.RefusedN then Bot.RefusedN[serviceName] = 0 end
            if type(after) == "number" and type(afterUse) == "number" then
                knowNoteCooldown(moveValue.Name, after - afterUse)
            end
        end
    end)
    debug("Used: " .. moveValue.Name .. " [" .. serviceName .. "]")

    Life.lastUsed, Life.lastUsedAt = moveValue.Name, tick()
    return true
end










local function canChase()
    local i = getInfo()
    if i and i:FindFirstChild("DisableChase") then return false end
    if isStunned() or isRagdolled() then return false end
    return tick() - (Bot.LastChase or 0) > Config.ChaseCooldown
end

local function useChase()
    if not canChase() then return false end
    local svc = getMovesetService()
    if not svc then return false end

    Bot.LastChase = tick()
    local ok = fireRemote(svc, "Chase", isAirborne(), "Front")
    if ok and Config.DebugDash then
        debug("chase fired (air=" .. tostring(isAirborne()) .. ")")
    end
    return ok
end







local function getSpecialRule()
    local c = getChar()
    local set = c and c:GetAttribute("Moveset")
    return set and SpecialRules[set] or nil, set
end

local function isSpecialReady()
    local c = getChar()
    if not c then return false end











    if tick() - (Bot.LastSpecial or 0) < Config.SpecialCooldown then
        return false
    end

    local cd = c:GetAttribute("M2_CD")
    local last = c:GetAttribute("LastM2")
    if type(cd) == "number" and type(last) == "number" and cd > 0 and last > 0 then
        if Workspace:GetServerTimeNow() < (last + cd) then return false end
    end

    return true
end


local function doParkour()
    local c = getChar()
    local h = getHRP()
    local hu = getHum()
    if not (c and h and hu) then return false end
    return callMC("Parkour", c, h, hu)
end

local function useSpecial()
    local rule, set = getSpecialRule()
    if not rule or rule.kind == "avoid" then return false end




    if rule.kind == "offense" and type(allyInBlast) == "function"
       and FriendlyGeom[senseMoveKey(rule.name)] and allyInBlast(rule.name, nil) then
        return false
    end

    local svc = getMovesetService()
    if not svc then return false end



    Bot.LastSpecial = tick()

    local ok
    if set == "Todo" then
        ok = fireRemote(svc, "RightActivated", Bot.Target)
    elseif set == "Naoya" or set == "Hanami" then
        ok = fireRemote(svc, "RightActivated", getAimPoint(), Bot.Target)
    elseif set == "MeiMei" then
        ok = fireRemote(svc, "RightActivated", getMoveVector())
    else
        ok = fireRemote(svc, "RightActivated", Bot.Target)
    end

    if not ok then return false end


    local holdFor = (rule.kind == "hold") and Config.SpecialHold or 0.12
    task.delay(holdFor, function()
        fireRemote(svc, "RightDeactivated")
    end)




    Bot.LastSkill = tick()
    Bot.LastOffense = tick()
    memRecordUse("SPECIAL:" .. rule.name, Bot.Target, Bot.Dist2D)
    debug("Special: " .. rule.name .. " (" .. rule.kind .. ")")


    Life.lastUsed, Life.lastUsedAt = rule.name, tick()
    return true
end








































function dashVector(dir)
    local h = getHRP()
    if not h then return nil end
    local cf = h.CFrame
    if dir == "Front" then return cf.LookVector end
    if dir == "Back"  then return -cf.LookVector end
    if dir == "Left"  then return -cf.RightVector end
    if dir == "Right" then return cf.RightVector end
    return cf.LookVector
end

function getMovementForce()
    local h = getHRP()
    if not h then return nil end
    local mf = h:FindFirstChild("MovementForce")
    if mf and mf:IsA("BodyVelocity") then return mf end

    for _, d in ipairs(h:GetChildren()) do
        if d:IsA("BodyVelocity") then return d end
    end
    return nil
end

local function dash(dir)



    if tick() - (Bot.LastDash or 0) < Config.DashCooldown then return false end

    local h = getHRP()
    local p0 = h and h.Position
    if not h then return false end

    Bot.LastDash = tick()


    local sent = fireRemote("MovementService", "Dash", dir)


    local vec = dashVector(dir)
    if vec then
        Bot.DashDir = vec
        Bot.DashSpeed = Config.DashSpeed
        Bot.DashUntil = tick() + Config.DashTime
    end

    if Config.DebugDash and p0 then
        task.delay(0.4, function()
            local h2 = getHRP()
            if not h2 then return end
            debug(string.format("dash %s sent=%s moved=%.1f",
                tostring(dir), tostring(sent), (h2.Position - p0).Magnitude))
        end)
    end
    return true
end


function tickDash()
    if not Bot.DashUntil or tick() > Bot.DashUntil then
        Bot.DashDir = nil
        return
    end
    if not Bot.DashDir then return end

    local mf = getMovementForce()
    if not mf then return end


    Bot.DashSpeed = Bot.DashSpeed * Config.DashDecay
    mf.Velocity = Vector3.new(
        Bot.DashDir.X * Bot.DashSpeed,
        mf.Velocity.Y,
        Bot.DashDir.Z * Bot.DashSpeed)
end




function dashDirFor(vec)
    local h = getHRP()
    if not h or not vec then return "Back" end
    local flat = Vector3.new(vec.X, 0, vec.Z)
    if flat.Magnitude < 0.05 then return "Back" end
    flat = flat.Unit
    local cf = h.CFrame
    local best, bestDot = "Back", -math.huge
    local opts = {
        Front = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z),
        Back  = Vector3.new(-cf.LookVector.X, 0, -cf.LookVector.Z),
        Right = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z),
        Left  = Vector3.new(-cf.RightVector.X, 0, -cf.RightVector.Z),
    }
    for name, v in pairs(opts) do
        if v.Magnitude > 0.05 then
            local d = v.Unit:Dot(flat)
            if d > bestDot then best, bestDot = name, d end
        end
    end
    return best
end











function tryBurst()
    if not Config.UseBurst then return false end
    local now = tick()
    if now - (Bot.BurstAt or 0) < (Bot.BurstQuick and 0.35 or (Config.BurstCooldown or 2)) then return false end
    if not (isStunned() or isRagdolled()) then return false end
    local c, i = getChar(), getInfo()
    if not c or not i then return false end
    if i:FindFirstChild("Wakeup") or i:GetAttribute("Wakeup") then return false end
    local fe = i:FindFirstChild("ForceEsc")
    local can = (i:FindFirstChild("Knockback") ~= nil)
             or (c:GetAttribute("Burst") and not i:GetAttribute("Burst"))
             or (fe ~= nil and fe.Value == true)
    if not can then return false end
    local h = getHRP()
    if not h then return false end
    local from = Bot.Aggressor and getHRP(Bot.Aggressor)
    if not from or (from.Position - h.Position).Magnitude > (Config.BurstRange or 12) then
        from = nil
        local best





        for _, e in ipairs(Bot.HitCandidates or {}) do
            local eh = getHRP(e)
            if eh and not isAllyName(e.Name) then
                local dd = (eh.Position - h.Position).Magnitude
                if dd <= (Config.BurstRange or 12) and (not best or dd < best) then best, from = dd, eh end
            end
        end
    end
    if not from then return false end
    local away = Vector3.new(h.Position.X - from.Position.X, 0, h.Position.Z - from.Position.Z)
    if away.Magnitude < 0.1 then away = Vector3.new(-h.CFrame.LookVector.X, 0, -h.CFrame.LookVector.Z) end
    local dir = tacEscapeDir(h, from, dashDirFor(away))
    Bot.BurstAt = now
    Life.bursts = (Life.bursts or 0) + 1
    -- the meter says whether an escape is on offer (the character's Burst
    -- attribute, as the game's own bar reads it). Knockback alone lets the
    -- request through but the server turns it down: try again soon, and do
    -- not behave as if we had escaped.
    local real = (c:GetAttribute("Burst") and not i:GetAttribute("Burst")) or (fe ~= nil and fe.Value == true)
    Bot.BurstQuick = not real



    if real and (Config.PostBurstRecover or 0) > 0 and (from.Position - h.Position).Magnitude <= (Config.BurstRecoverRange or 8)
       and getHPPct() < (Config.BurstRecoverHP or 70) then
        local u = away.Unit
        local a = math.rad((math.random() * 2 - 1) * (Config.BurstRecoverJitter or 35))
        Bot.RecoverDir = Vector3.new(u.X * math.cos(a) - u.Z * math.sin(a), 0, u.X * math.sin(a) + u.Z * math.cos(a))
        Bot.RecoverMode = (math.random() < (Config.BurstRecoverStep or 0.65)) and "away" or "hold"
        Bot.RecoverUntil = now + (Config.PostBurstRecover or 1.2)
        Bot.RecoverSaid = false
    end
    fireRemote("MovementService", "Dash", dir, true)
    debugEvery("burst", 2, string.format("burst: escape %s (enemy %.0f studs)", dir, (from.Position - h.Position).Magnitude))
    return true
end

function dashWorld(vec)
    local h = getHRP()
    if not h or not vec then return false end
    local flat = Vector3.new(vec.X, 0, vec.Z)
    if flat.Magnitude < 0.05 then return false end
    flat = flat.Unit

    local cf = h.CFrame
    local best, bestDot = "Front", -math.huge
    local opts = {
        Front = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z),
        Back  = Vector3.new(-cf.LookVector.X, 0, -cf.LookVector.Z),
        Right = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z),
        Left  = Vector3.new(-cf.RightVector.X, 0, -cf.RightVector.Z),
    }
    for name, v in pairs(opts) do
        if v.Magnitude > 0.05 then
            local d = v.Unit:Dot(flat)
            if d > bestDot then best, bestDot = name, d end
        end
    end
    return dash(best)
end

function dashToward()  dash("Front") end

function dashSideways()
    if math.random() < 0.5 then dash("Left") else dash("Right") end
end














function releaseBlock()
    if not Bot.BlockActive then return end
    do
        local nowR = tick()
        local held = nowR - (Bot.BlockSince or nowR)
        local swings = Bot.BlockSwings or 0
        local predicted = Bot.PreGuardAt ~= nil and Bot.BlockSince ~= nil and Bot.PreGuardAt >= Bot.BlockSince - 0.1
        if predicted and swings > 0 then Life.tacGuardHit = (Life.tacGuardHit or 0) + 1 end
        -- A string that was blocked through to its end leaves its owner in
        -- recovery. That is the surest opening there is: take it.
        if (Config.TacPunish or 0) > 0 and swings > 0 and held >= 0.25
           and not isStunned() and not isRagdolled() then
            Bot.PunishUntil = math.max(Bot.PunishUntil or 0, nowR + Config.TacPunish)
            Bot.PunishFromBlock = nowR
            Life.tacPunish = (Life.tacPunish or 0) + 1
        end
        if predicted then Bot.PreGuardAt = nil end
    end
    if Bot.BlockHeld then
        debugEvery("defendheld", 0.2, string.format("DEFEND held %.1f s, swings %d",
            tick() - (Bot.BlockSince or tick()), Bot.BlockSwings or 0))
    end
    Bot.BlockSwings, Bot.SwingName = 0, nil
    Bot.BlockActive = false
    Bot.BlockKeptSaid = false
    Bot.BlockHeld = false
    Bot.BlockUntil = 0
    Bot.BlockReleasedAt = tick()
    fireRemote("BlockService", "Deactivated")
end






function guardTarget()
    return (Bot.State == "DEFEND" and Bot.DefendVs) or Bot.Target
end

function doBlock(hold)
    local now = tick()
    local dur = hold or Config.BlockDuration


    if hold and now - (Bot.BlockReleasedAt or 0) < (Config.DefendCapRest or 0.3) then return end
    if Bot.BlockActive then
        if hold then
            local cap = (Bot.BlockSince or now) + (Config.BlockHoldMax or 2.0)
            Bot.BlockUntil = math.min(math.max(Bot.BlockUntil or 0, now + dur), cap)
            Bot.BlockHeld = true
        end
        return
    end
    stopM1()
    Life.blocks = (Life.blocks or 0) + 1
    local vs = guardTarget()
    fireRemote("BlockService", "Activated", vs)
    Bot.BlockTarget = vs
    Bot.BlockActive = true
    Bot.BlockHeld = hold ~= nil
    Bot.BlockSince = now
    Bot.BlockUntil = now + dur
    Bot.LastBlock = now
    task.spawn(function()
        while Bot.BlockActive and tick() < (Bot.BlockUntil or 0) do
            task.wait(0.05)
        end
        if Bot.BlockActive then releaseBlock() end
    end)
end




function doUltimate()
    stopM1()
    local svc = getMovesetService()
    if not svc then return end
    fireRemote(svc, "Ultimate")
    debug("Triggered awakening")
end



DangerByService = {
    -- game 1.85: Hired Hunter, Register's awakening, Sky Bender's fourth
    Flourish =                  "rush",
    Debilitate =                "rush",
    Transcend =                 "rush",
    Rupture =                   "rush",
    Lasso =                     "pull",
    Whiplash =                  "beam",
