function heapLine()
    local every = Config.HeapLineEvery or 60
    if every <= 0 then return end
    local nowC = os.clock()
    if nowC - (Bot.ProbeAt or 0) >= 1 then
        Bot.ProbeAt = nowC
        local t0 = os.clock()
        for _ = 1, 2000 do local _ = os.clock() end
        local ring = Bot.ProbeRing
        if not ring then ring = {}; Bot.ProbeRing = ring end
        local i = (Bot.ProbeI or 0) % 60 + 1
        ring[i] = (os.clock() - t0) * 1e6
        Bot.ProbeI = i
    end
    if nowC - (Bot.HeapAt or 0) < every then return end
    Bot.HeapAt = nowC
    local function count(tb)
        local n, dead = 0, 0
        if type(tb) == "table" then
            for k in pairs(tb) do
                n = n + 1
                if typeof(k) == "Instance" and k.Parent == nil then dead = dead + 1 end
            end
        end
        return n, dead
    end
    local okH, heap = pcall(collectgarbage, "count")
    if not okH or type(heap) ~= "number" then heap = -1 end
    local probe, ring = -1, Bot.ProbeRing
    if ring and #ring > 0 then
        local tmp = {}
        for i = 1, #ring do tmp[i] = ring[i] end
        table.sort(tmp)
        probe = tmp[math.ceil(#tmp / 2)]
    end
    local eN, eD = count(Enemy)
    local fx = Workspace:FindFirstChild("Effects")
    debugEvery("heap", every, string.format(
        "heap %.0f KB | ours: Enemy %d (dead %d) SpeedNorm %d SenseHooked %d Threat %d DmgFrom %d BadTargets %d pending %d opponents %d debugOnceAt %d | fx %d players %d | probe %.0f us",
        heap, eN, eD, (count(SpeedNorm)), (count(SenseHooked)), (count(Threat)), (count(Bot.DmgFrom)),
        (count(Bot.BadTargets)), #pending, (count(MEM.opponents)), (count(debugOnceAt)),
        fx and #fx:GetChildren() or 0, #Players:GetPlayers(), probe))
end

-- ---------------------------------------------------------------- respawn
-- Game 1.85 stopped respawning the dead. ToolController shows Main.Respawn
-- while the body carries CanRespawn and Info has no NoRes (attribute or
-- child; a private-server setting), and both the button and the Special key
-- fire JoinService.Respawn with no arguments. Nothing answers on failure, so
-- the request is simply repeated until the character changes.
function respawnOffered(c)
    c = c or getChar()
    if not c or not c.Parent then return false end
    if not c:GetAttribute("CanRespawn") then return false end
    local info = c:FindFirstChild("Info")
    if info and (info:GetAttribute("NoRes") or info:FindFirstChild("NoRes")) then return false end
    return true
end

function autoRespawnTick()
    if not Config.AutoRespawn or not AutoState.wantOn then
        AutoState.respawnSeenAt = nil
        return
    end
    local c = getChar()
    if not c or isAlive(c) or not respawnOffered(c) then
        AutoState.respawnSeenAt = nil
        AutoState.respawnTries = 0
        return
    end
    local now = tick()
    AutoState.respawnSeenAt = AutoState.respawnSeenAt or now
    if now - AutoState.respawnSeenAt < (Config.RespawnDelay or 0.4) then return end
    if now - (AutoState.respawnAt or 0) < (Config.RespawnRetry or 1.0) then return end
    AutoState.respawnAt = now
    AutoState.respawnTries = (AutoState.respawnTries or 0) + 1
    local sent = fireRemote("JoinService", "Respawn")
    if AutoState.respawnTries == 1 or AutoState.respawnTries % 10 == 0 then
        debug(string.format("respawn: offered, asking (try %d, %s)", AutoState.respawnTries,
            sent and "sent" or "JoinService.Respawn missing - older server?"))
    end
end

-- -------------------------------------------------------------- aim reply
-- Road Rage and House (Register's 1.85 awakening) do not take their aim at
-- activation. The server sends the caster Effects("Hitbox", ...) carrying a
-- throwaway RemoteEvent and the game client streams its mouse point into it
-- (Road Rage: every 0.025 s while the remote lives; House: every 0.1 s until
-- a BoolValue flips, then once more). The game's own controller still does
-- that with wherever the camera looks; this adds the target's feet to the
-- stream so the last word is usually ours.
do
    local function aimPoint()
        local t = Bot.Target
        local th = t and getHRP(t)
        local p = (th and th.Position) or getAimPoint()
        local rp = RaycastParams.new()
        pcall(function()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            local skip = {}
            for _, n in ipairs({ "Characters", "Effects", "Logic" }) do
                local f = Workspace:FindFirstChild(n)
                if f then skip[#skip + 1] = f end
            end
            rp.FilterDescendantsInstances = skip
        end)
        local hit = Workspace:Raycast(p + Vector3.new(0, 1, 0), Vector3.new(0, -300, 0), rp)
        return hit and hit.Position or p
    end
    local function isRemote(x)
        return typeof(x) == "Instance" and (x.ClassName == "RemoteEvent" or x.ClassName == "UnreliableRemoteEvent")
    end
    local function stream(remote, flag, every, maxFor)
        if not isRemote(remote) then return end
        task.spawn(function()
            local t0 = tick()
            while remote.Parent and tick() - t0 < maxFor do
                if not (Config.AimReply and Config.Enabled) then break end
                pcall(function() remote:FireServer(aimPoint()) end)
                if flag and flag.Value == true then break end
                task.wait(every)
            end
        end)
    end
    local function hook(serviceName, onHitbox)
        local svc = getService(serviceName)
        local fx = svc and svc.Effects
        if type(fx) ~= "table" or type(fx.Connect) ~= "function" then return false end
        local ok = pcall(function()
            fx:Connect(function(key, ...)
                if key ~= "Hitbox" or not Config.AimReply then return end
                pcall(onHitbox, ...)
            end)
        end)
        return ok
    end
    task.delay(4, function()
        local a = hook("RoadRageService", function(remote)
            stream(remote, nil, 0.03, 10)
        end)
        local b = hook("HouseService", function(flag, remote)
            if typeof(flag) == "Instance" and flag:IsA("BoolValue") then
                stream(remote, flag, 0.08, 10)
            else
                stream(isRemote(flag) and flag or remote, nil, 0.08, 10)
            end
        end)
        debug(string.format("aim reply: RoadRage %s, House %s", a and "hooked" or "absent", b and "hooked" or "absent"))
    end)
end

-- The cues for a second press (see Know.P2) arrive on the same Effects
-- signals the game's own controllers listen to.
do
    local function hookFx(serviceName)
        local svc = getService(serviceName)
        local fx = svc and svc.Effects
        if type(fx) ~= "table" or type(fx.Connect) ~= "function" then return false end
        local ok = pcall(function()
            fx:Connect(function(key, ...) pcall(knowP2Event, serviceName, key, ...) end)
        end)
        if ok then Know.p2Hooked[serviceName] = true end
        return ok
    end
    task.delay(4.5, function()
        local said = {}
        for _, name in ipairs({ "TranscendService", "RuptureService", "ReggieService", "DroneStrikeService" }) do
            said[#said + 1] = (string.gsub(name, "Service", "")) .. " " .. (hookFx(name) and "hooked" or "absent")
        end
        debug("second press: " .. table.concat(said, ", "))
    end)
end

task.spawn(function()
    while task.wait(0.2) do
        pcall(autoRespawnTick)
        pcall(function()
            if AutoState.wantOn and not Config.Enabled and isAlive() then
                if AutoState.pendingChar or AutoState.queued then
                    AutoState.idleSince = nil
                else
                    AutoState.idleSince = AutoState.idleSince or os.clock()
                    if os.clock() - AutoState.idleSince > Config.WatchdogIdle then
                        AutoState.idleSince = nil
                        debug("watchdog: should be running but is not - starting")
                        pcall(startBot)
                    end
                end
            else
                AutoState.idleSince = nil
            end
        end)
        pcall(autoCheckWastedLife)
        pcall(heapLine)
    end
end)









-- ============================================================================
--  THE EYE  --  HUD (overlay build)
--
--  No panel. Three things sit over the game:
--    * the Eye: a small lidless eye at the top of the screen, breathing a
--      soft halo while the bot pilots, dim and still while it sleeps. Drag it
--      anywhere; tap it to open the menu.
--    * the readout: three lines under the eye saying what the bot is doing,
--      who it is on, and why. Hidden while the menu is open.
--    * the aura: a glow around the edge of the whole screen in the dominion's
--      colour while the bot is piloting, like a browser tab under remote
--      control. Red-shifted and quicker when the fighter is bleeding.
--  The menu is a plain serif list on the left with a glowing marker on the
--  chosen line, no box behind it.
--
--  Two dominions: Barad-dur (ember) and Minas Morgul (witch-light). The eye
--  itself is a PNG embedded below and written to the executor workspace on
--  first use, so it draws without any Roblox asset id; executors without
--  getcustomasset get a vector stand-in.
-- ============================================================================

local FF_ENV = (typeof(getgenv) == "function" and getgenv()) or _G
local FF_THEME_FILE = "JJK_EyeTheme.txt"
local TweenService = game:GetService("TweenService")

local Theme = {
    name  = "baraddur",
    order = { "baraddur", "morgul" },
    conns = nil,
    rebuild = nil,
    reopenMenu = nil,
}

Theme.defs = {
    baraddur = {
        label   = "Barad-dur",
        txt     = Color3.fromRGB(236, 226, 210),
        dim     = Color3.fromRGB(170, 150, 130),
        accent  = Color3.fromRGB(255, 92, 20),     -- ember
        accent2 = Color3.fromRGB(255, 214, 96),    -- molten
        bad     = Color3.fromRGB(230, 30, 30),
        ink     = Color3.fromRGB(8, 4, 3),
        font    = Enum.Font.Garamond,
        fontM   = Enum.Font.Code,
        smoke   = Color3.fromRGB(255, 46, 10),     -- body of the aura
        wisp    = Color3.fromRGB(255, 150, 40),    -- bright tendrils
        rune    = Color3.fromRGB(255, 200, 110),   -- the ring of runes
        runeHot = Color3.fromRGB(255, 244, 200),   -- a rune as it flares
        title   = "BARAD-DÛR",
        sub     = "the eye is upon them",
        awake   = "Awaken the Eye",
        sleep   = "Close the Eye",
        idle    = "the eye sleeps",
    },
    morgul = {
        label   = "Minas Morgul",
        txt     = Color3.fromRGB(220, 240, 228),
        dim     = Color3.fromRGB(130, 170, 150),
        accent  = Color3.fromRGB(70, 255, 110),    -- witch-light
        accent2 = Color3.fromRGB(200, 255, 220),
        bad     = Color3.fromRGB(230, 30, 30),
        ink     = Color3.fromRGB(3, 8, 5),
        font    = Enum.Font.Garamond,
        fontM   = Enum.Font.Code,
        smoke   = Color3.fromRGB(0, 170, 50),
        wisp    = Color3.fromRGB(140, 255, 130),
        rune    = Color3.fromRGB(190, 255, 205),
        runeHot = Color3.fromRGB(236, 255, 240),
        title   = "MINAS MORGUL",
        sub     = "the dead do not sleep",
        awake   = "Raise the Dead",
        sleep   = "Let Them Rest",
        idle    = "the tower is silent",
    },
}

function Theme.p()
    local d = Theme.defs[Theme.name]
    if d == nil then return Theme.defs.baraddur end
    return d
end

function Theme.dropConns()
    local c = Theme.conns
    Theme.conns = nil
    if type(c) ~= "table" then return end
    for _, conn in ipairs(c) do
        pcall(function() conn:Disconnect() end)
    end
end

function Theme.set(name, quiet)
    if Theme.defs[name] == nil then return false end
    Theme.name = name
    pcall(function() rawset(FF_ENV, "__JJK_EYE_THEME", name) end)
    if type(writefile) == "function" then pcall(writefile, FF_THEME_FILE, name) end
    if type(Theme.rebuild) == "function" then
        Theme.dropConns()
        local ok, err = pcall(Theme.rebuild)
        if not ok then
            debug("[theme] rebuild failed: " .. tostring(err))
            return false
        end
    end
    if not quiet then debug("[theme] " .. tostring(Theme.p().label)) end
    return true
end

function Theme.cycle()
    local at = 1
    for i, n in ipairs(Theme.order) do
        if n == Theme.name then at = i end
    end
    local nxt = Theme.order[at + 1]
    if nxt == nil then nxt = Theme.order[1] end
    return Theme.set(nxt)
end

do
    local saved = rawget(FF_ENV, "__JJK_EYE_THEME")
    if type(saved) ~= "string" and type(readfile) == "function" and type(isfile) == "function" then
        local okE, exists = pcall(isfile, FF_THEME_FILE)
        if okE and exists then
            local ok, raw = pcall(readfile, FF_THEME_FILE)
            if ok and type(raw) == "string" then saved = raw end
        end
    end
    if type(saved) == "string" and Theme.defs[saved] ~= nil then
        Theme.name = saved
    end
end

-- -------------------------------------------------------------- the art
-- Every picture the HUD draws, embedded as PNG. The eye comes in two
-- dominions; everything else is a grayscale + alpha layer the client tints
-- with the dominion's colours. Written to the workspace as
-- JJK_Eye_<name>_v4.png on first use and loaded through getcustomasset.
local ASSET_PNG = {
    eye_baraddur = "",
    eye_morgul   = "",
    shade  = "",    -- dark vignette in the corners
    smoke  = "",    -- the slow body of the aura
    wispsA = "",   -- bright tendrils, two seeds crossfaded so it churns
    wispsB = "",
    runes_base = "",  -- the ring of cirth along the screen's edge, lit softly
    runes_s1 = "",      -- four groups of those runes that flare on their own
    runes_s2 = "",
    runes_s3 = "",
    runes_s4 = "",
    eye_fireA = "",    -- tongues of fire swirling round the eye, two seeds
    eye_fireB = "",
    eye_smoke = "",    -- the smoke they rise through
    menu_haze = "",    -- a brushed dark smear the menu text sits on
    hp_frame  = "",     -- the barbed iron frame of a health bar
    fx_flame  = "",     -- particle: a tongue of fire / a puff of smoke
    fx_ember  = "",     -- particle: a spark
    fx_circle = "",    -- the ring of runes on the ground under our feet
    fx_sigil  = "",     -- the star and the eye inside that ring
}

local function b64decode(s)
    if typeof(crypt) == "table" and type(crypt.base64decode) == "function" then
        local ok, r = pcall(crypt.base64decode, s)
        if ok and type(r) == "string" and #r > 0 then return r end
    end
    if type(base64_decode) == "function" then
        local ok, r = pcall(base64_decode, s)
        if ok and type(r) == "string" and #r > 0 then return r end
    end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local index = {}
    for i = 1, 64 do index[string.sub(alphabet, i, i)] = i - 1 end
    s = string.gsub(s, "[^%w%+/=]", "")
    local out, n, bits, nb = {}, 0, 0, 0
    for i = 1, #s do
        local c = string.sub(s, i, i)
        if c == "=" then break end
        bits = bits * 64 + index[c]
        nb = nb + 6
        if nb >= 8 then
            nb = nb - 8
            local div = 2 ^ nb
            n = n + 1
            out[n] = string.char(math.floor(bits / div) % 256)
            bits = bits % div
        end
    end
    return table.concat(out)
end

local function loadAsset(name)
    local cache = rawget(FF_ENV, "__JJK_EYE_ASSETS")
    if type(cache) ~= "table" then cache = {}; rawset(FF_ENV, "__JJK_EYE_ASSETS", cache) end
    if cache[name] ~= nil then return cache[name] or nil end
    local id = false
    pcall(function()
        if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then return end
        if type(ASSET_PNG[name]) ~= "string" or #ASSET_PNG[name] < 16 then return end
        local file = "JJK_Eye_" .. name .. "_v4.png"
        local have = false
        if type(isfile) == "function" then
            local okF, ex = pcall(isfile, file)
            have = okF and ex == true
        end
        if not have then writefile(file, b64decode(ASSET_PNG[name])) end
        local got = getcustomasset(file)
        if type(got) == "string" and #got > 0 then id = got end
    end)
    cache[name] = id
    return id or nil
end

-- Ember mode: the one thermal lever a phone needs, kept as a menu line
-- instead of being forced at load. Quality floor + fps cap on, back off.
Config.EmberMode = false
if Config.MordorBars == nil then Config.MordorBars = true end
if Config.Aura == nil then Config.Aura = true end
local function applyEmberMode(on)
    pcall(function()
        local ugs = UserSettings():GetService("UserGameSettings")
        ugs.SavedQualityLevel = on and Enum.SavedQualitySetting.QualityLevel1
                                   or Enum.SavedQualitySetting.Automatic
    end)
    pcall(function()
        if typeof(setfpscap) == "function" then
            setfpscap(on and (tonumber(FF_ENV.JJK_PhoneFpsCap) or 30) or 0)
        end
    end)
end

-- What the state machine is doing, in words a person would use.
local STATE_WORD = {
    IDLE = "Watching", APPROACH = "Closing in", ATTACK = "Striking", CHASE = "Hunting",
    RETREAT = "Withdrawing", DEFEND = "Guarding", FLANK = "Circling", PUNISH = "Punishing",
    REACT = "Reacting", CCED = "Stunned", THROW = "Throwing", AWAKEN = "Awakening",
    DEAD = "Fallen", LEVEL = "Climbing", PERCHED = "Perched", TEAMKITE = "Kiting",
}

do
    local function buildHUD()

        local TP      = Theme.p()
        local TXT     = TP.txt
        local DIM     = TP.dim
        local ACCENT  = TP.accent
        local ACCENT2 = TP.accent2
        local BAD     = TP.bad
        local INK     = TP.ink
        local FONT    = TP.font
        local FONTM   = TP.fontM

        local function mk(class, props)
            local o = Instance.new(class)
            for k, v in pairs(props) do
                if k ~= "Parent" then o[k] = v end
            end
            if props.Parent then o.Parent = props.Parent end
            return o
        end
        local function round(o, r)
            local c = Instance.new("UICorner")
            c.CornerRadius = r and UDim.new(0, r) or UDim.new(1, 0)
            c.Parent = o
            return c
        end
        local function stroke(o, colour, thick, trans)
            return mk("UIStroke", {
                Color = colour, Thickness = thick or 1, Transparency = trans or 0,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = o,
            })
        end
        local function tween(o, t, props, style, dir)
            local ok, tw = pcall(function()
                return TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Sine,
                    dir or Enum.EasingDirection.InOut), props)
            end)
            if ok and tw then tw:Play() end
            return ok and tw or nil
        end
        local function short(s, n)
            s = tostring(s or "?")
            if #s > n then return string.sub(s, 1, n - 1) .. "." end
            return s
        end
        local function fmtClock(sec)
            sec = math.max(0, math.floor(tonumber(sec) or 0))
            return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
        end
        local function nameOf(char, fallback)
            if not char then return fallback or "?" end
            local ok, plr = pcall(function() return Players:GetPlayerFromCharacter(char) end)
            if ok and plr then return plr.Name end
            if fallback then return fallback end
            local ok2, n = pcall(function() return char.Name end)
            if ok2 and n then return n end
            return "?"
        end
        local function numOf(fn, arg)
            local ok, v = pcall(fn, arg)
            if ok and type(v) == "number" then return v end
            return 0
        end
        -- Text drawn straight over the game needs a dark edge to stay legible.
        local function text(props)
            props.BackgroundTransparency = 1
            props.Font = props.Font or FONT
            props.TextStrokeColor3 = INK
            props.TextStrokeTransparency = props.TextStrokeTransparency or 0.55
            props.TextTruncate = props.TextTruncate or Enum.TextTruncate.AtEnd
            return mk("TextLabel", props)
        end

        -- ------------------------------------------------------------ parent
        local parentTarget = nil
        local okCore, coreGui = pcall(function() return game:GetService("CoreGui") end)
        if okCore and coreGui then parentTarget = coreGui end
        if typeof(gethui) == "function" then
            local okHui, hidden = pcall(gethui)
            if okHui and hidden then parentTarget = hidden end
        end
        if not parentTarget then
            parentTarget = LocalPlayer:WaitForChild("PlayerGui")
        end
        pcall(function()
            for _, child in ipairs(parentTarget:GetChildren()) do
                if child:GetAttribute("EyeHUD") or child:GetAttribute("FocusFightHUD") then
                    child:Destroy()
                end
            end
        end)

        local gui = mk("ScreenGui", {
            Name = "EYE_" .. tostring(math.random(100000, 999999)), ResetOnSpawn = false,
            IgnoreGuiInset = true, DisplayOrder = 999,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        })
        pcall(function() gui:SetAttribute("EyeHUD", true) end)
        gui.Parent = parentTarget

        local conns = {}
        Theme.conns = conns
        local function bind(signal, fn)
            local c = signal:Connect(fn)
            table.insert(conns, c)
            return c
        end
        -- set further down, by the health bars and the aura of the body
        local barsEnable, barsDestroy, auraSet, auraEnable, auraDestroy = nil, nil, nil, nil, nil

        -- Drag by a handle; a press that barely moves counts as a tap.
        local function draggable(handle, target, onTap)
            local dragging, startPos, origin, moved = false, nil, nil, false
            bind(handle.InputBegan, function(input)
                if input.UserInputType ~= Enum.UserInputType.MouseButton1
                   and input.UserInputType ~= Enum.UserInputType.Touch then return end
                dragging, moved = true, false
                startPos, origin = input.Position, target.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                        if not moved and onTap then pcall(onTap) end
                    end
                end)
            end)
            bind(UserInputService.InputChanged, function(input)
                if not dragging or not startPos then return end
                if input.UserInputType ~= Enum.UserInputType.MouseMovement
                   and input.UserInputType ~= Enum.UserInputType.Touch then return end
                local delta = input.Position - startPos
                if delta.Magnitude > 6 then moved = true end
                if moved then
                    target.Position = UDim2.new(origin.X.Scale, origin.X.Offset + delta.X,
                                                origin.Y.Scale, origin.Y.Offset + delta.Y)
                end
            end)
        end

        -- -------------------------------------------------------------- aura
        -- Full-screen picture layers: a dark shade in the corners, the smoke,
        -- two sets of tendrils crossfaded against each other so the fire
        -- moves, and the ring of runes. Each is grayscale, tinted here. If
        -- the executor cannot load pictures, five soft strokes stand in.
        local auraRoot = mk("Frame", {
            Name = "Aura", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1,
            Visible = false, ZIndex = 1, Parent = gui,
        })
        local auraLayers = {}     -- name -> ImageLabel
        local auraStrokes = {}    -- fallback
        do
            local order = { "shade", "smoke", "wispsA", "wispsB", "runes_base", "runes_s1", "runes_s2", "runes_s3", "runes_s4" }
            local ok = true
            for _, nm in ipairs(order) do if not loadAsset(nm) then ok = false end end
            if ok then
                for i, nm in ipairs(order) do
                    auraLayers[nm] = mk("ImageLabel", {
                        Name = nm, Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1,
                        Image = loadAsset(nm), ImageTransparency = 1,
                        ScaleType = Enum.ScaleType.Stretch, ZIndex = i, Parent = auraRoot,
                    })
                end
            else
                local AURA = { { 6, 0.40 }, { 14, 0.58 }, { 26, 0.72 }, { 42, 0.84 }, { 64, 0.92 } }
                for i, def in ipairs(AURA) do
                    local t = def[1]
                    local f = mk("Frame", {
                        Size = UDim2.new(1, -2 * t, 1, -2 * t), Position = UDim2.new(0, t, 0, t),
                        BackgroundTransparency = 1, ZIndex = 1, Parent = auraRoot,
                    })
                    round(f, 18 + t)
                    auraStrokes[i] = { stroke = stroke(f, ACCENT, t, 1), base = def[2] }
                end
            end
        end
        local function auraTint(hot)
            local smoke = hot and Color3.fromRGB(255, 24, 18) or TP.smoke
            local wisp  = hot and Color3.fromRGB(255, 96, 60) or TP.wisp
            local rune  = hot and Color3.fromRGB(255, 170, 150) or TP.rune
            if auraLayers.smoke then
                auraLayers.shade.ImageColor3  = Color3.new(0, 0, 0)
                auraLayers.smoke.ImageColor3  = smoke
                auraLayers.wispsA.ImageColor3 = wisp
                auraLayers.wispsB.ImageColor3 = wisp
                auraLayers.runes_base.ImageColor3 = rune
                for i = 1, 4 do auraLayers["runes_s" .. i].ImageColor3 = hot and Color3.fromRGB(255, 220, 210) or TP.runeHot end
            end
            for _, e in ipairs(auraStrokes) do e.stroke.Color = hot and BAD or ACCENT end
        end
        auraTint(false)

        -- --------------------------------------------------------------- eye
        local EYE = 96           -- the big eye: about a tenth of a phone's width
        local eyeRoot = mk("Frame", {
            Name = "Eye", AnchorPoint = Vector2.new(0.5, 0), Size = UDim2.new(0, EYE * 2, 0, EYE * 2),
            Position = UDim2.new(0.5, 0, 0, -16), BackgroundTransparency = 1, ZIndex = 10,
            Parent = gui,
        })
        -- The fire round the eye: smoke, then two sets of tongues that turn
        -- against each other and trade places, so it never repeats. Two discs
        -- stand in if the pictures cannot load.
        local FIRE = EYE * 2.9
        local fireA, fireB, fireSmoke, halo1, halo2, ring = nil, nil, nil, nil, nil, nil
        if loadAsset("eye_fireA") and loadAsset("eye_fireB") and loadAsset("eye_smoke") then
            local function fireLayer(nm, size, z)
                return mk("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                    Size = UDim2.new(0, size, 0, size), BackgroundTransparency = 1,
                    Image = loadAsset(nm), ImageColor3 = TP.wisp, ImageTransparency = 1,
                    ScaleType = Enum.ScaleType.Fit, ZIndex = z, Parent = eyeRoot,
                })
            end
            fireSmoke = fireLayer("eye_smoke", FIRE * 1.15, 9)
            fireSmoke.ImageColor3 = TP.smoke
            fireA = fireLayer("eye_fireA", FIRE, 10)
            fireB = fireLayer("eye_fireB", FIRE * 0.92, 11)
            fireB.Rotation = 137
        else
            halo2 = mk("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.new(0, EYE + 44, 0, EYE + 44), BackgroundColor3 = ACCENT,
                BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 10, Parent = eyeRoot,
            })
            round(halo2)
            halo1 = mk("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.new(0, EYE + 18, 0, EYE + 18), BackgroundColor3 = ACCENT,
                BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 11, Parent = eyeRoot,
            })
            round(halo1)
            ring = stroke(halo1, ACCENT2, 1, 1)
        end

        local eyeImg = nil
        local asset = loadAsset("eye_" .. Theme.name)
        if asset then
            eyeImg = mk("ImageLabel", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.new(0, EYE, 0, EYE), BackgroundTransparency = 1,
                Image = asset, ScaleType = Enum.ScaleType.Fit, ZIndex = 12, Parent = eyeRoot,
            })
        else
            -- Vector stand-in: a disc of fire with a black slit.
            eyeImg = mk("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.new(0, EYE, 0, EYE), BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, ZIndex = 12, Parent = eyeRoot,
            })
            round(eyeImg)
            local g = Instance.new("UIGradient")
            g.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, BAD), ColorSequenceKeypoint.new(0.35, ACCENT),
                ColorSequenceKeypoint.new(0.5, ACCENT2), ColorSequenceKeypoint.new(0.65, ACCENT),
                ColorSequenceKeypoint.new(1, BAD),
            })
            g.Parent = eyeImg
            local slit = mk("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.new(0, 7, 1, -8), BackgroundColor3 = INK, BorderSizePixel = 0,
                ZIndex = 13, Parent = eyeImg,
            })
            round(slit)
        end
        local function setEyeTint(c, t)
            pcall(function()
                if eyeImg:IsA("ImageLabel") then
                    eyeImg.ImageColor3 = c
                    eyeImg.ImageTransparency = t
                else
                    eyeImg.BackgroundColor3 = c
                    eyeImg.BackgroundTransparency = t
                end
            end)
        end

        -- A transparent button over the eye: the drag handle and the menu tap.
        local eyeTap = mk("TextButton", {
            Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "",
            AutoButtonColor = false, ZIndex = 14, Parent = eyeRoot,
        })
        -- The eye blinks now and then (a horizontal shut, since the slit is
        -- upright) and glances about: toward its target when it has one.
        local Camera = workspace.CurrentCamera
        local lookX, lookY = 0, 0
        task.spawn(function()
            while gui and gui.Parent do
                local t = Bot.Target
                local h = t and t:FindFirstChild("HumanoidRootPart")
                local want = nil
                if h and Camera then
                    local ok, v, on = pcall(function()
                        local p, onScreen = Camera:WorldToViewportPoint(h.Position)
                        return p, onScreen
                    end)
                    if ok and v and on then
                        local vp = Camera.ViewportSize
                        want = { ((v.X / vp.X) - 0.5) * 2, ((v.Y / vp.Y) - 0.5) * 2 }
                    end
                end
                if not want then
                    want = { (math.random() - 0.5) * 2, (math.random() - 0.5) * 1.2 }
                end
                lookX = math.clamp(want[1], -1, 1) * EYE * 0.15
                lookY = math.clamp(want[2], -1, 1) * EYE * 0.08
                tween(eyeImg, 0.28, { Position = UDim2.new(0.5, lookX, 0.5, lookY) },
                    Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                task.wait(h and (0.6 + math.random() * 0.9) or (1.2 + math.random() * 2.4))
            end
        end)
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(3 + math.random() * 5)
                local blinks = (math.random() < 0.25) and 2 or 1
                for _ = 1, blinks do
                    tween(eyeImg, 0.09, { Size = UDim2.new(0, EYE, 0, 5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                    task.wait(0.1)
                    tween(eyeImg, 0.14, { Size = UDim2.new(0, EYE, 0, EYE) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                    task.wait(0.2)
                end
            end
        end)

        -- ----------------------------------------------------------- readout
        local hazeAsset = loadAsset("menu_haze")
        local readout = mk("Frame", {
            AnchorPoint = Vector2.new(0.5, 0), Size = UDim2.new(0, 460, 0, 50),
            Position = UDim2.new(0.5, 0, 1, 12), BackgroundTransparency = 1, ZIndex = 10,
            Parent = eyeRoot,
        })
        local l1 = text({ Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0),
            Text = "", TextSize = 36, TextColor3 = ACCENT2, TextStrokeTransparency = 0.25,
            ZIndex = 11, Parent = readout })

        -- ------------------------------------------------------- health bars
        -- Mordor bars over every fighter, ours included: barbed iron caps, a
        -- blood fill (the dominion's colour on our own), and a pale ghost that
        -- lingers where the health was a moment ago. The engine's own name
        -- and health display is switched off per humanoid while these are up
        -- and put back when they are turned off.
        do
            local barFolder = mk("Folder", { Name = "EYE_bars", Parent = parentTarget })
            pcall(function() barFolder:SetAttribute("EyeHUD", true) end)
            local frameAsset = loadAsset("hp_frame")
            local IRON = Color3.fromRGB(190, 180, 165)
            local HOLE_X, HOLE_Y, HOLE_W, HOLE_H = 15, 6, 120, 6
            local bars = {}
            -- what each humanoid's own display was before we hid it; shared across
            -- HUD rebuilds so a dominion change never mistakes "hidden" for the original
            local saved = rawget(FF_ENV, "__JJK_EYE_HUMSAVED")
            if type(saved) ~= "table" then
                saved = setmetatable({}, { __mode = "k" })
                rawset(FF_ENV, "__JJK_EYE_HUMSAVED", saved)
            end
            local enabled = false

            local function hideDefault(hum)
                pcall(function()
                    if not saved[hum] then
                        saved[hum] = { hum.HealthDisplayType, hum.DisplayDistanceType }
                    end
                    if hum.HealthDisplayType ~= Enum.HumanoidHealthDisplayType.AlwaysOff then
                        hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
                    end
                    if hum.DisplayDistanceType ~= Enum.HumanoidDisplayDistanceType.None then
                        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    end
                end)
            end
            local function restoreDefault()
                for hum, s in pairs(saved) do
                    pcall(function()
                        hum.HealthDisplayType = s[1]
                        hum.DisplayDistanceType = s[2]
                    end)
                    saved[hum] = nil
                end
            end

            local function makeBar(char, isSelf)
                local head = char:FindFirstChild("Head") or getHRP(char)
                if not head then return nil end
                local bb = mk("BillboardGui", {
                    Name = "bar", Adornee = head, Size = UDim2.new(0, 190, 0, 50),
                    StudsOffset = Vector3.new(0, 2.6, 0), AlwaysOnTop = false, LightInfluence = 0,
                    MaxDistance = 260, ResetOnSpawn = false, Parent = barFolder,
                })
                local root = mk("Frame", {
                    AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0),
                    Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Parent = bb,
                })
                local sc = mk("UIScale", { Scale = 1, Parent = root })
                local name = text({
                    Size = UDim2.new(1, 0, 0, 22), Position = UDim2.new(0, 0, 0, 2), Text = "",
                    TextSize = 18, TextColor3 = TXT, TextStrokeTransparency = 0.35, Parent = root,
                })
                local holder = mk("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 27),
                    Size = UDim2.new(0, 150, 0, 18), BackgroundTransparency = 1, Parent = root,
                })
                local back = mk("Frame", {
                    Position = UDim2.new(0, HOLE_X, 0, HOLE_Y), Size = UDim2.new(0, HOLE_W, 0, HOLE_H),
                    BackgroundColor3 = INK, BackgroundTransparency = 0.25, BorderSizePixel = 0,
                    ZIndex = 1, Parent = holder,
                })
                local ghost = mk("Frame", {
                    Position = UDim2.new(0, HOLE_X, 0, HOLE_Y), Size = UDim2.new(0, HOLE_W, 0, HOLE_H),
                    BackgroundColor3 = Color3.fromRGB(255, 240, 220), BorderSizePixel = 0,
                    ZIndex = 2, Parent = holder,
                })
                local fill = mk("Frame", {
                    Position = UDim2.new(0, HOLE_X, 0, HOLE_Y), Size = UDim2.new(0, HOLE_W, 0, HOLE_H),
                    BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 3, Parent = holder,
                })
                local g = Instance.new("UIGradient")
                if isSelf then
                    g.Color = ColorSequence.new(TP.accent, TP.accent2)
                else
                    g.Color = ColorSequence.new(Color3.fromRGB(120, 8, 8), Color3.fromRGB(236, 52, 28))
                end
                g.Parent = fill
                local frame = nil
                if frameAsset then
                    frame = mk("ImageLabel", {
                        Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Image = frameAsset,
                        ImageColor3 = IRON, ScaleType = Enum.ScaleType.Stretch, ZIndex = 4, Parent = holder,
                    })
                else
                    stroke(back, IRON, 1, 0.2)
                end
                return { bb = bb, head = head, scale = sc, name = name, ghost = ghost, fill = fill,
                         frame = frame, isSelf = isSelf, pct = nil, token = 0, label = nil }
            end

            local function drop(c)
                local r = bars[c]
                if r then pcall(function() r.bb:Destroy() end) end
                bars[c] = nil
            end

            local function update()
                if not enabled then return end
                local cam = workspace.CurrentCamera
                local camPos = cam and cam.CFrame.Position
                local mine = getChar()
                local manual = (Bot.LockMode == "MANUAL") and Bot.LockedName ~= nil
                local list = getChars()
                if mine and mine.Parent and not table.find(list, mine) then table.insert(list, mine) end
                local seen = {}
                for _, c in ipairs(list) do
                    local hum = c:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        local r = bars[c]
                        if not r then
                            r = makeBar(c, c == mine)
                            bars[c] = r
                        end
                        if r then
                            seen[c] = true
                            hideDefault(hum)
                            local pct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                            if pct ~= r.pct then
                                r.fill.Size = UDim2.new(0, HOLE_W * pct, 0, HOLE_H)
                                if r.pct and pct < r.pct then
                                    -- the ghost holds, then drains to meet the fill
                                    r.token = r.token + 1
                                    local tk = r.token
                                    task.delay(0.3, function()
                                        if r.token == tk and r.ghost.Parent then
                                            tween(r.ghost, 0.5, { Size = UDim2.new(0, HOLE_W * (r.pct or 0), 0, HOLE_H) },
                                                Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                                        end
                                    end)
                                else
                                    r.ghost.Size = UDim2.new(0, HOLE_W * pct, 0, HOLE_H)
                                end
                                r.pct = pct
                            end
                            -- a fighter near death: the fill gutters
                            r.fill.BackgroundTransparency = (pct < 0.25)
                                and (0.4 * (0.5 + 0.5 * math.sin(os.clock() * 10))) or 0

                            local nm = nameOf(c)
                            local isTarget = (c == Bot.Target)
                            local branded = manual and Bot.LockedName == nm
                            local label = (branded and "† " or "") .. short(nm, 18)
                            if r.label ~= label then r.name.Text = label; r.label = label end
                            r.name.TextColor3 = (r.isSelf or isTarget) and ACCENT2 or TXT
                            if r.frame then
                                r.frame.ImageColor3 = isTarget and ACCENT2 or (r.isSelf and TP.rune or IRON)
                            end
                            if camPos and r.head.Parent then
                                local d = (r.head.Position - camPos).Magnitude
                                r.scale.Scale = math.clamp(42 / math.max(d, 1), 0.55, 1)
                            end
                        end
                    end
                end
                for c in pairs(bars) do
                    if not seen[c] then drop(c) end
                end
            end

            barsEnable = function(v)
                enabled = v and true or false
                if not enabled then
                    for c in pairs(bars) do drop(c) end
                    restoreDefault()
                end
            end
            barsDestroy = function()
                barsEnable(false)
                pcall(function() barFolder:Destroy() end)
            end
            task.spawn(function()
                while gui and gui.Parent do
                    local ok, err = pcall(update)
                    if not ok then debugEvery("hudbars", 10, "[HUD] bars: " .. tostring(err)) end
                    task.wait(0.1)
                end
                pcall(barsDestroy)
            end)
            barsEnable(Config.MordorBars)
        end

        -- ------------------------------------------------- the aura of the body
        -- What rises off our own fighter: tongues of fire and dark smoke from
        -- the chest, embers, a low mist at the feet, two ribbons of shadow
        -- streaming off the back like a torn cloak, a light, and a sigil
        -- turning on the ground beneath. All of it lives on two unseen parts
        -- under the camera that follow the character, so nothing is added to
        -- the character itself, nothing replicates, and nothing can be hit,
        -- touched or found by a spatial query.
        do
            local cam = workspace.CurrentCamera
            pcall(function()
                for _, ch in ipairs(cam:GetChildren()) do
                    if ch:GetAttribute("EyeAura") then ch:Destroy() end
                end
            end)
            local folder = mk("Folder", { Name = "EYE_aura", Parent = cam })
            pcall(function() folder:SetAttribute("EyeAura", true) end)

            local function ghostPart(size)
                return mk("Part", {
                    Size = size, Transparency = 1, Anchored = true, CanCollide = false,
                    CanTouch = false, CanQuery = false, CastShadow = false, Massless = true,
                    Parent = folder,
                })
            end
            local core = ghostPart(Vector3.new(1, 1, 1))
            local function att(pos) return mk("Attachment", { Position = pos, Parent = core }) end
            local chest, feet = att(Vector3.new(0, 0.2, 0)), att(Vector3.new(0, -2.7, 0))

            local flameTex = loadAsset("fx_flame") or "rbxasset://textures/particles/fire_main.dds"
            local smokeTex = loadAsset("fx_flame") or "rbxasset://textures/particles/smoke_main.dds"
            local emberTex = loadAsset("fx_ember") or "rbxasset://textures/particles/sparkles_main.dds"
            local CSK, NSK = ColorSequenceKeypoint.new, NumberSequenceKeypoint.new
            local dark = TP.smoke:Lerp(Color3.new(0, 0, 0), 0.82)
            local flameCol = ColorSequence.new({ CSK(0, TP.accent2), CSK(0.35, TP.wisp), CSK(1, TP.smoke) })
            local flameHot = ColorSequence.new({ CSK(0, Color3.fromRGB(255, 230, 200)), CSK(0.35, Color3.fromRGB(255, 90, 50)),
                                                 CSK(1, Color3.fromRGB(160, 10, 10)) })

            local flames = mk("ParticleEmitter", {
                Texture = flameTex, Color = flameCol, LightEmission = 0.85, LightInfluence = 0,
                Size = NumberSequence.new({ NSK(0, 1.1), NSK(0.4, 2.3), NSK(1, 0.8) }),
                Transparency = NumberSequence.new({ NSK(0, 1), NSK(0.15, 0.45), NSK(0.7, 0.7), NSK(1, 1) }),
                Lifetime = NumberRange.new(0.8, 1.5), Rate = 0, Speed = NumberRange.new(2, 4.5),
                Acceleration = Vector3.new(0, 6, 0), SpreadAngle = Vector2.new(28, 28),
                Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-70, 70),
                EmissionDirection = Enum.NormalId.Top, LockedToPart = false, Parent = chest,
            })
            local smoke = mk("ParticleEmitter", {
                Texture = smokeTex, Color = ColorSequence.new(dark, Color3.new(0, 0, 0)),
                LightEmission = 0, LightInfluence = 0,
                Size = NumberSequence.new({ NSK(0, 1.8), NSK(1, 4.6) }),
                Transparency = NumberSequence.new({ NSK(0, 1), NSK(0.2, 0.5), NSK(1, 1) }),
                Lifetime = NumberRange.new(1.5, 2.4), Rate = 0, Speed = NumberRange.new(1.5, 3),
                Acceleration = Vector3.new(0, 3.5, 0), SpreadAngle = Vector2.new(35, 35),
                Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-40, 40),
                EmissionDirection = Enum.NormalId.Top, LockedToPart = false, Parent = chest,
            })
            local embers = mk("ParticleEmitter", {
                Texture = emberTex, Color = ColorSequence.new(TP.accent2, TP.wisp),
                LightEmission = 1, LightInfluence = 0,
                Size = NumberSequence.new({ NSK(0, 0.3), NSK(1, 0) }),
                Transparency = NumberSequence.new({ NSK(0, 0), NSK(0.8, 0.2), NSK(1, 1) }),
                Lifetime = NumberRange.new(1.2, 2.2), Rate = 0, Speed = NumberRange.new(4, 9),
                Acceleration = Vector3.new(0, 7, 0), Drag = 1.2, SpreadAngle = Vector2.new(70, 70),
                EmissionDirection = Enum.NormalId.Top, LockedToPart = false, Parent = chest,
            })
            local mist = mk("ParticleEmitter", {
                Texture = smokeTex, Color = ColorSequence.new(TP.smoke:Lerp(Color3.new(0, 0, 0), 0.45), dark),
                LightEmission = 0.35, LightInfluence = 0,
                Size = NumberSequence.new({ NSK(0, 2.2), NSK(1, 4.4) }),
                Transparency = NumberSequence.new({ NSK(0, 1), NSK(0.25, 0.68), NSK(1, 1) }),
                Lifetime = NumberRange.new(1.2, 2), Rate = 0, Speed = NumberRange.new(2, 4.5),
                Acceleration = Vector3.new(0, -1, 0), SpreadAngle = Vector2.new(85, 85),
                Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-30, 30),
                EmissionDirection = Enum.NormalId.Top, LockedToPart = false, Parent = feet,
            })
            local light = mk("PointLight", {
                Color = TP.accent, Range = 14, Brightness = 0, Shadows = false, Parent = core,
            })
            local ribbons = {}
            for _, x in ipairs({ -0.85, 0.85 }) do
                -- the back of a Roblox character is +Z
                ribbons[#ribbons + 1] = mk("Trail", {
                    Attachment0 = att(Vector3.new(x, 1.3, 0.55)), Attachment1 = att(Vector3.new(x, -1.9, 0.55)),
                    Lifetime = 0.5, MinLength = 0.05, LightEmission = 0.4, LightInfluence = 0,
                    Color = ColorSequence.new(dark, TP.smoke),
                    Transparency = NumberSequence.new({ NSK(0, 0.45), NSK(1, 1) }),
                    WidthScale = NumberSequence.new({ NSK(0, 1), NSK(1, 0.25) }),
                    Enabled = false, Parent = core,
                })
            end

            -- the sigil on the ground: a ring of runes turning one way, the
            -- star and the eye inside it turning the other
            local sig, circleImg, sigilImg = nil, nil, nil
            if loadAsset("fx_circle") and loadAsset("fx_sigil") then
                sig = ghostPart(Vector3.new(11, 0.05, 11))
                local sg = mk("SurfaceGui", {
                    Face = Enum.NormalId.Top, CanvasSize = Vector2.new(512, 512), LightInfluence = 0,
                    Brightness = 2, Parent = sig,
                })
                circleImg = mk("ImageLabel", {
                    Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Image = loadAsset("fx_circle"),
                    ImageColor3 = TP.rune, ImageTransparency = 1, Parent = sg,
                })
                sigilImg = mk("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
                    Size = UDim2.new(0.84, 0, 0.84, 0), BackgroundTransparency = 1, Image = loadAsset("fx_sigil"),
                    ImageColor3 = TP.wisp, ImageTransparency = 1, Parent = sg,
                })
            end

            local on = Config.Aura and true or false
            local awake, hot, shown = false, false, false
            local lightBase, sigBase = 0, 1
            local function apply()
                local k = shown and (awake and 1 or 0.35) or 0
                flames.Rate = (hot and 28 or 18) * k
                smoke.Rate  = 7 * k
                embers.Rate = (hot and 26 or 12) * k
                mist.Rate   = 9 * k
                flames.Color = hot and flameHot or flameCol
                light.Color = hot and BAD or TP.accent
                lightBase = shown and (awake and 1.7 or 0.6) or 0
                sigBase = shown and (awake and 0.2 or 0.68) or 1
                for _, r in ipairs(ribbons) do r.Enabled = shown end
                if circleImg then
                    circleImg.ImageColor3 = hot and Color3.fromRGB(255, 190, 170) or TP.rune
                    sigilImg.ImageColor3 = hot and Color3.fromRGB(255, 70, 50) or TP.wisp
                end
            end

            local rp = RaycastParams.new()
            pcall(function() rp.FilterType = Enum.RaycastFilterType.Exclude end)
            local groundY, groundAt, spin = nil, 0, 0
            bind(RunService.RenderStepped, function(dt)
                local h = on and getHRP() or nil
                if not h or not isAlive() then
                    if shown then
                        shown = false
                        apply()
                        light.Brightness = 0
                        if circleImg then circleImg.ImageTransparency = 1; sigilImg.ImageTransparency = 1 end
                    end
                    return
                end
                if not shown then shown = true; apply() end
                core.CFrame = h.CFrame
                local now = os.clock()
                light.Brightness = lightBase * (0.82 + 0.18 * math.sin(now * 3.1))
                if sig then
                    if now - groundAt > 0.12 then
                        groundAt = now
                        local skip = { folder }
                        local chars = Workspace:FindFirstChild("Characters")
                        if chars then skip[#skip + 1] = chars end
                        local mine = getChar()
                        if mine then skip[#skip + 1] = mine end
                        rp.FilterDescendantsInstances = skip
                        local hit = Workspace:Raycast(h.Position, Vector3.new(0, -16, 0), rp)
                        groundY = hit and hit.Position.Y or nil
                    end
                    if groundY then
                        sig.CFrame = CFrame.new(h.Position.X, groundY + 0.12, h.Position.Z)
                        spin = spin + (dt or 0.016) * (hot and 70 or 24)
                        circleImg.Rotation = spin
                        sigilImg.Rotation = -spin * 0.6
                        local a = math.clamp(sigBase + 0.12 * math.sin(now * 2.2), 0, 1)
                        circleImg.ImageTransparency = a
                        sigilImg.ImageTransparency = math.min(1, a + 0.15)
                    else
                        circleImg.ImageTransparency = 1
                        sigilImg.ImageTransparency = 1
                    end
                end
            end)

            auraSet = function(open, isHot)
                awake, hot = open and true or false, isHot and true or false
                apply()
            end
            auraEnable = function(v)
                on = v and true or false
            end
            auraDestroy = function()
                pcall(function() folder:Destroy() end)
            end
        end

        -- -------------------------------------------------------------- menu
        local MENU_W = 440
        local menu = mk("Frame", {
            Name = "Menu", AnchorPoint = Vector2.new(0, 0.5), Size = UDim2.new(0, MENU_W, 1, -40),
            Position = UDim2.new(0, 28, 0.5, 0), BackgroundTransparency = 1, Visible = false,
            ZIndex = 20, Parent = gui,
        })
        if hazeAsset then
            -- the brushed dark smear the words sit on, soft at every edge
            mk("ImageLabel", {
                Size = UDim2.new(1, 220, 1, 120), Position = UDim2.new(0, -120, 0, -60),
                BackgroundTransparency = 1, Image = hazeAsset, ImageColor3 = Color3.new(0, 0, 0),
                ImageTransparency = 0.12, ScaleType = Enum.ScaleType.Stretch, ZIndex = 20, Parent = menu,
            })
        end
        local mTitle = text({ Size = UDim2.new(1, 0, 0, 58), Position = UDim2.new(0, 0, 0, 0),
            Text = TP.title, TextSize = 52, TextColor3 = TXT, TextXAlignment = Enum.TextXAlignment.Left,
            TextStrokeTransparency = 0.4, Active = true, ZIndex = 21, Parent = menu })
        local mSub = text({ Size = UDim2.new(1, 0, 0, 24), Position = UDim2.new(0, 2, 0, 56),
            Text = TP.sub, TextSize = 20, TextColor3 = DIM, TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 21, Parent = menu })
        -- the diamond rule under the title
        local mRule = mk("Frame", {
            Size = UDim2.new(0, 300, 0, 1), Position = UDim2.new(0, 0, 0, 88),
            BackgroundColor3 = ACCENT, BorderSizePixel = 0, ZIndex = 21, Parent = menu,
        })
        do
            local g = Instance.new("UIGradient")
            g.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1),
            })
            g.Parent = mRule
        end
        local mDiamond = mk("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0, 7, 0, 7),
            Position = UDim2.new(0, 90, 0, 88), Rotation = 45, BackgroundColor3 = ACCENT2,
            BorderSizePixel = 0, ZIndex = 22, Parent = menu,
        })

        local list = mk("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, -102), Position = UDim2.new(0, 0, 0, 102),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2,
            ScrollBarImageColor3 = ACCENT, ScrollBarImageTransparency = 0.5,
            CanvasSize = UDim2.new(0, 0, 0, 0), ZIndex = 21, Parent = menu,
        })

        local function setMenu(open)
            menu.Visible = open
            readout.Visible = not open
        end
        draggable(eyeTap, eyeRoot, function() setMenu(not menu.Visible) end)
        draggable(mTitle, menu, nil)

        local lastToggle = 0
        local function toggleBot()
            if os.clock() - lastToggle < 0.35 then return end
            lastToggle = os.clock()
            if Config.Enabled then AutoState.wantOn = false end
            local ok, err = pcall(function()
                if Config.Enabled then stopBot() else startBot() end
            end)
            if not ok then debug("start/stop failed: " .. tostring(err)) end
        end

        local function brand(i)
            local d = (Bot.Scores or {})[i]
            if not d or not d.char then return end
            local nm = nameOf(d.char, d.name)
            if Bot.LockMode == "MANUAL" and Bot.LockedName == nm then
                Bot.LockMode = "AUTO"; Bot.LockedName = nil
                debug("[HUD] mark released (" .. tostring(nm) .. ")")
            else
                Bot.LockMode = "MANUAL"; Bot.LockedName = nm
                debug("[HUD] branded -> " .. tostring(nm))
            end
        end

        -- The menu is pages. The root is short, like a pause menu; each line
        -- that opens a page lists its own runes. `key` toggles a Config flag
        -- and shows its state, `fn` runs once, `dyn` is a ranked target,
        -- `page` opens a sub-page, `back` returns to the root.
        local PAGES = {}
        PAGES.root = {
            { fn = toggleBot, label = function() return Config.Enabled and TP.sleep or TP.awake end, hot = true },
            { page = "combat",   label = "Combat" },
            { page = "tactics",  label = "Tactics" },
            { page = "marked",   label = "The Marked" },
            { page = "map",      label = "Map" },
            { page = "learning", label = "Learning" },
            { page = "items",    label = "Items" },
            { page = "settings", label = "Settings" },
            { fn = function() setMenu(false) end, label = "Resume" },
        }
        PAGES.combat = {
            { back = true },
            { key = "BodyLock",    label = "Body lock-on",
              on = function(v) if not v then releaseBody() end end },
            { key = "UseSkills",   label = "Use skills" },
            { key = "UseSpecial",  label = "Use special" },
            { key = "UseBlock",    label = "Use block" },
            { key = "Sprint",      label = "Sprint",
              on = function(v) if not v then local hum = getHum(); if hum then hum.WalkSpeed = 16 end end end },
            { key = "AutoRespawn", label = "Auto respawn",
              on = function(v) announce(v and "auto respawn: the bot presses Respawn when it is offered" or "auto respawn off - press Respawn yourself") end },
            { fn = function()
                  local ready, since = autoCanChange()
                  if not ready then
                      announce(string.format("change on cooldown - %.0fs left",
                          Config.CharChangeCooldown - since))
                      return
                  end
                  autoSwitchNow()
              end, label = "Swap character now" },
        }
        -- The model-based rules (v85). Each is independent, and each has its
        -- own counters in the LIFE END line of the log.
        PAGES.tactics = {
            { back = true },
            { key = "TacCombo",      label = "Chain off a landed hit",
              on = function(v) announce(v and "tactics: skills chain the moment a hit is confirmed" or "tactics: chaining off") end },
            { key = "TacDiscipline", label = "Hold skills for a hit",
              on = function(v) announce(v and "tactics: in melee, skills wait for a confirmed hit" or "tactics: skills thrown freely in melee") end },
            { key = "TacGuard",      label = "Block before the swing",
              on = function(v) announce(v and "tactics: blocking on time-to-contact" or "tactics: blocking only on a seen swing") end },
            { key = "TacLead",       label = "Lead the target",
              on = function(v) announce(v and "tactics: aiming where the target will be" or "tactics: aiming at the target's current position") end },
            { key = "TacCastGate",   label = "No casts while stunned" },
            { key = "TacFaceTravel", label = "Face the way we run",
              on = function(v) announce(v and "movement: body faces the travel direction until in fighting distance" or "movement: body held on the target at all times") end },
            { key = "TacBlockKeep",  label = "Keep a raised block up",
              on = function(v) announce(v and "tactics: a block stays up at least 0.3 s" or "tactics: blocks drop the moment their reason is gone") end },
            { key = "TacMoveDamp",   label = "Steady footing",
              on = function(v) announce(v and "movement: reversals must persist before they are obeyed" or "movement: every direction change obeyed at once") end },
            { page = "know", label = "Move knowledge" },
            { page = "sense", label = "Fight sense" },
        }
        -- The moments that decide a fight (v89, v90).
        PAGES.sense = {
            { back = true },
            { key = "TacDashOpen", label = "Open with a dash punch",
              on = function(v) announce(v and "tactics: the front-dash punch opens the fight from 11 to 18 studs" or "tactics: the dash punch is only used to run somebody down") end },
            { key = "TacWake",     label = "Wake-up rules",
              on = function(v) announce(v and "tactics: swing through on getting up, guard when they get up" or "tactics: no special handling of getting up") end },
            { key = "TacAwaken",   label = "Awaken when it counts",
              on = function(v) announce(v and "tactics: awakening waits for low health, a helpless target or 15 s" or "tactics: awakening the moment the bar fills") end },
            { key = "TacEscapeSide", label = "Escape to the side",
              on = function(v) announce(v and "tactics: knockdown escapes go sideways, toward the middle" or "tactics: knockdown escapes go straight back") end },
            { key = "TacLedger",   label = "Log how hits get in" },
        }
        -- What each move is for (v87): researched facts, corrected by what
        -- the machine measures on its own casts. See the KNOW lines in the log.
        PAGES.know = {
            { back = true },
            { key = "Know",        label = "Know what moves do",
              on = function(v) announce(v and "knowledge: casts are weighed by their chance to land on the target as it is" or "knowledge: off - casts go by range alone") end },
            { key = "KnowCounter", label = "Counter into swings",
              on = function(v) announce(v and "knowledge: counters are thrown into a swing, never raw" or "knowledge: counters are not used") end },
            { key = "KnowM1Hold",  label = "Keep wasted swings",
              on = function(v) announce(v and "knowledge: no basic attacks into a guard or at a body on the ground" or "knowledge: basic attacks never held") end },
            { key = "KnowProbe",   label = "Probe the unknown",
              on = function(v) announce(v and "knowledge: up to three test casts a life where nothing is known" or "knowledge: no test casts") end },
            { key = "KnowSecondPress", label = "Press twice where needed",
              on = function(v) announce(v and "knowledge: two-press moves get their second press" or "knowledge: every move is tapped once") end },
            { key = "KnowHold",    label = "Hold where it pays",
              on = function(v) announce(v and "knowledge: held versions are tried at a distance and kept if they deal more" or "knowledge: every move is let go at once") end },
            { fn = function()
                  local order = { "auto", "down", "up", "flat", "off" }
                  local cur = Config.TacFinisher or "auto"
                  local nxt = order[1]
                  for i, m in ipairs(order) do if m == cur then nxt = order[(i % #order) + 1] end end
                  Config.TacFinisher = nxt
                  announce("fourth hit: " .. nxt .. ((nxt == "auto") and " (tries each, keeps what pays)" or ""))
              end, label = "Change the fourth hit" },
        }
        PAGES.marked = {
            { back = true },
            { dyn = 1, fn = function() brand(1) end },
            { dyn = 2, fn = function() brand(2) end },
            { dyn = 3, fn = function() brand(3) end },
            { fn = function() Bot.LockMode = "AUTO"; Bot.LockedName = nil; debug("[HUD] mark released") end,
              label = "Release the mark", onlyWhen = function() return Bot.LockMode == "MANUAL" and Bot.LockedName ~= nil end },
            { key = "PlayersOnly", label = "Players only",
              on = function() Bot.Target = nil end },
        }
        PAGES.map = {
            { back = true },
            { key = "UsePathfinding", label = "Pathfinding" },
            { key = "MapMemory",   label = "Map memory",
              on = function(v)
                  if v then
                      local n, counts, links = mapStats()
                      announce(string.format("map on: %d cells, %d hot, %d rich, %d routes",
                          n, counts.HOT, counts.RICH, links))
                  else announce("map off") end
              end },
        }
        PAGES.learning = {
            { back = true },
            { key = "Memory",      label = "Memory",
              on = function(v)
                  if v then announce("memory on -> " .. MemIO.file)
                  else memSave(true); announce("memory off (saved)") end
              end },
            { key = "Sense",       label = "Sense opponent moves",
              on = function(v)
                  announce(v and ("sense on: " .. senseHookCount() .. " services hooked") or "sense off")
              end },
            { key = "AutoRestart", label = "Auto restart and swap",
              on = function(v)
                  Config.AutoCharacter = v
                  if v then
                      announce("auto: restart on death + character swap")
                      local rep = memCharReport()
                      if rep ~= "" then announce("best so far: " .. rep) end
                  else announce("auto off") end
              end },
            { key = "CharSwitchEveryLife", label = "New character every life",
              on = function(v) announce(v and "new character every life" or "swap every few lives") end },
        }
        PAGES.items = {
            { back = true },
            { fn = function() itemScan(140) end,               label = "Scan nearby" },
            { fn = itemPickup,                                 label = "Pick up nearest" },
            { fn = function() announce("held: " .. itemHeld()); senseThrowHeld(Bot.Target) end,
                                                                label = "Throw (auto)" },
            { fn = itemThrowM1,                                label = "Throw (M1)" },
            { fn = itemThrowM2,                                label = "Throw (M2)" },
            { fn = itemRefire,                                 label = "Re-fire throwable" },
            { fn = itemDrop,                                   label = "Drop" },
        }
        PAGES.settings = {
            { back = true },
            { theme = true,        label = "Dominion" },
            { key = "MordorBars",  label = "Mordor health bars",
              on = function(v) if barsEnable then barsEnable(v) end end },
            { key = "Aura",        label = "Aura of the body",
              on = function(v) if auraEnable then auraEnable(v) end end },
            { key = "EmberMode",   label = "Ember mode",
              on = function(v) applyEmberMode(v); announce(v and "ember mode: fps capped, quality floored" or "ember mode off") end },
            { key = "DebugTarget", label = "Debug target picks" },
            { key = "DebugDash",   label = "Log everything",
              on = function(v)
                  Config.DebugMoves = v; Config.DebugM1 = v; Config.DebugTrace = v
                  Config.DebugSense = v; Config.DebugMap = v
                  LOG.enabled = v
                  if v then
                      if LOG.canWrite then
                          announce("logging to " .. LOG.name)
                          pcall(logSnapshot)
                          logFlush(true)
                      else
                          announce("no writefile in this executor - logging to console")
                      end
                  else
                      logFlush(true)
                      if LOG.canWrite then
                          announce("log saved: " .. LOG.name .. " (" .. #LOG.lines .. " lines)")
                      end
                  end
              end },
            { fn = function()
                  for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
                  if barsDestroy then pcall(barsDestroy) end
                  if auraDestroy then pcall(auraDestroy) end
                  gui:Destroy()
                  debug("[HUD] closed")
              end, label = "Quit the HUD" },
        }
        local PAGE_TITLE = { combat = "Combat", tactics = "Tactics", marked = "The Marked", map = "Map",
                             learning = "Learning", items = "Items", settings = "Settings" }

        local ROW_H = 52
        local pageName, ROWS, items, selected = "root", nil, {}, 1
        local showPage -- forward

        local function layout()
            local y = 0
            for i, def in ipairs(ROWS) do
                local it = items[i]
                local show = true
                if def.onlyWhen then show = def.onlyWhen() and true or false end
                if def.dyn then show = (Bot.Scores or {})[def.dyn] ~= nil end
                it.frame.Visible = show
                if show then
                    it.frame.Position = UDim2.new(0, 0, 0, y)
                    y = y + ROW_H
                end
            end
            list.CanvasSize = UDim2.new(0, 0, 0, y + 8)
        end

        local function buildRows()
            for _, ch in ipairs(list:GetChildren()) do
                if ch:IsA("GuiObject") then ch:Destroy() end
            end
            items = {}
            for i, def in ipairs(ROWS) do
                local row = mk("TextButton", {
                    Size = UDim2.new(1, 0, 0, ROW_H), BackgroundTransparency = 1, Text = "",
                    AutoButtonColor = false, ZIndex = 21, Parent = list,
                })
                -- the marker: a soft bar that fades to the right, and a diamond
                local hl = mk("Frame", {
                    Size = UDim2.new(1, -8, 0, ROW_H - 8), Position = UDim2.new(0, 8, 0, 4),
                    BackgroundColor3 = ACCENT, BorderSizePixel = 0, Visible = false, ZIndex = 21, Parent = row,
                })
                round(hl, 10)
                do
                    local g = Instance.new("UIGradient")
                    g.Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(0.6, 0.6),
                        NumberSequenceKeypoint.new(1, 1),
                    })
                    g.Parent = hl
                end
                stroke(hl, ACCENT2, 1, 0.7)
                local dia = mk("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0, 12, 0, 12),
                    Position = UDim2.new(0, 2, 0.5, 0), Rotation = 45, BackgroundColor3 = ACCENT2,
                    BorderSizePixel = 0, Visible = false, ZIndex = 23, Parent = row,
                })
                local lbl = text({
                    Size = UDim2.new(1, -140, 1, 0), Position = UDim2.new(0, 24, 0, 0),
                    Text = "", TextSize = def.back and 22 or 33, TextColor3 = def.back and DIM or TXT,
                    TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = row,
                })
                local val = text({
                    Size = UDim2.new(0, 130, 1, 0), Position = UDim2.new(1, -138, 0, 0),
                    Text = "", TextSize = 20, TextColor3 = DIM, TextXAlignment = Enum.TextXAlignment.Right,
                    ZIndex = 22, Parent = row,
                })
                items[i] = { frame = row, hl = hl, dia = dia, lbl = lbl, val = val }

                local last = 0
                row.MouseButton1Click:Connect(function()
                    if os.clock() - last < 0.25 then return end
                    last = os.clock()
                    selected = i
                    pcall(function()
                        if def.back then showPage("root") return end
                        if def.page then showPage(def.page) return end
                        if def.theme then
                            Theme.reopenMenu = pageName
                            task.defer(function() pcall(Theme.cycle) end)
                            return
                        end
                        if def.fn then
                            local ok, err = pcall(def.fn)
                            if not ok then debug(tostring(def.label) .. " failed: " .. tostring(err)) end
                            return
                        end
                        if def.key then
                            Config[def.key] = not Config[def.key]
                            if def.on then
                                local ok, err = pcall(def.on, Config[def.key])
                                if not ok then debug(def.label .. " failed: " .. tostring(err)) end
                            end
                            debug(string.format("[HUD] %s = %s", def.key, tostring(Config[def.key])))
                        end
                    end)
                end)
            end
        end

        local function syncMenu()
            local manual = (Bot.LockMode == "MANUAL") and Bot.LockedName ~= nil
            for i, def in ipairs(ROWS) do
                local it = items[i]
                if it then
                    local isSel = (i == selected)
                    it.hl.Visible = isSel
                    it.dia.Visible = isSel
                    it.lbl.TextColor3 = isSel and ACCENT2 or (def.back and DIM or (def.hot and ACCENT or TXT))
                    it.lbl.TextStrokeTransparency = isSel and 0.3 or 0.55
                    local label = def.label
                    if type(label) == "function" then label = label() end
                    if def.back then
                        label = "‹  Back"
                        it.val.Text = ""
                    elseif def.page then
                        it.val.Text = "›"
                        it.val.TextColor3 = DIM
                    elseif def.dyn then
                        local d = (Bot.Scores or {})[def.dyn]
                        if d then
                            local nm = nameOf(d.char, d.name)
                            local branded = manual and Bot.LockedName == nm
                            label = (branded and "† " or "") .. short(nm, 16)
                            it.val.Text = string.format("%d · %s", math.floor(tonumber(d.score) or 0), short(d.why or "-", 10))
                            it.val.TextColor3 = (d.char == Bot.Target) and ACCENT or DIM
                        else
                            label = ""
                            it.val.Text = ""
                        end
                    elseif def.theme then
                        it.val.Text = tostring(Theme.p().label)
                        it.val.TextColor3 = ACCENT
                    elseif def.key then
                        local on = Config[def.key] and true or false
                        it.val.Text = on and "on" or "off"
                        it.val.TextColor3 = on and ACCENT or DIM
                    else
                        it.val.Text = ""
                    end
                    it.lbl.Text = tostring(label or "")
                end
            end
            layout()
        end

        showPage = function(name)
            if not PAGES[name] then name = "root" end
            pageName = name
            ROWS = PAGES[name]
            selected = (name == "root") and 1 or 2
            mTitle.Text = (name == "root") and TP.title or string.upper(PAGE_TITLE[name] or name)
            mSub.Text = (name == "root") and TP.sub or TP.title
            buildRows()
            syncMenu()
            list.CanvasPosition = Vector2.new(0, 0)
        end
        showPage("root")

        if Theme.reopenMenu then
            local back = Theme.reopenMenu
            Theme.reopenMenu = nil
            if type(back) == "string" then showPage(back) end
            setMenu(true)
        end

        -- ------------------------------------------------------------- pulse
        local eyeOpen, eyeHot = nil, nil
        task.spawn(function()
            local phase = false
            while gui and gui.Parent do
                phase = not phase
                local period = eyeOpen and (eyeHot and 0.5 or 1.6) or 3.0
                if eyeOpen then
                    if fireA then
                        tween(fireA, period, { ImageTransparency = phase and 0.05 or 0.55 })
                        tween(fireB, period, { ImageTransparency = phase and 0.55 or 0.05 })
                        tween(fireSmoke, period, { ImageTransparency = phase and 0.25 or 0.45,
                            Size = UDim2.new(0, FIRE * (phase and 1.25 or 1.1), 0, FIRE * (phase and 1.25 or 1.1)) })
                    else
                        tween(halo1, period, { BackgroundTransparency = phase and 0.72 or 0.86,
                            Size = UDim2.new(0, EYE + (phase and 26 or 18), 0, EYE + (phase and 26 or 18)) })
                        tween(halo2, period, { BackgroundTransparency = phase and 0.88 or 0.95,
                            Size = UDim2.new(0, EYE + (phase and 60 or 44), 0, EYE + (phase and 60 or 44)) })
                        tween(ring, period, { Transparency = phase and 0.35 or 0.75 })
                    end
                    if auraLayers.smoke then
                        -- the smoke breathes, the tendrils trade places, the runes flicker
                        tween(auraLayers.shade,  period, { ImageTransparency = 0.05 })
                        tween(auraLayers.smoke,  period, { ImageTransparency = phase and 0.12 or 0.30 })
                        tween(auraLayers.wispsA, period, { ImageTransparency = phase and 0.05 or 0.70 })
                        tween(auraLayers.wispsB, period, { ImageTransparency = phase and 0.70 or 0.05 })
                        tween(auraLayers.runes_base, period, { ImageTransparency = phase and 0.25 or 0.5 })
                    end
                    for _, e in ipairs(auraStrokes) do
                        tween(e.stroke, period, { Transparency = e.base + (phase and -0.08 or 0.06) })
                    end
                else
                    if fireA then
                        tween(fireA, period, { ImageTransparency = phase and 0.78 or 0.9 })
                        tween(fireB, period, { ImageTransparency = phase and 0.9 or 0.78 })
                        tween(fireSmoke, period, { ImageTransparency = 0.88, Size = UDim2.new(0, FIRE, 0, FIRE) })
                    else
                        tween(halo1, period, { BackgroundTransparency = phase and 0.93 or 0.97,
                            Size = UDim2.new(0, EYE + 14, 0, EYE + 14) })
                        tween(halo2, period, { BackgroundTransparency = 1 })
                        tween(ring, period, { Transparency = 1 })
                    end
                end
                task.wait(period)
            end
        end)

        -- The fire turns: the two sets of tongues against each other, slowly.
        if fireA then
            task.spawn(function()
                local a, b = 0, 137
                while gui and gui.Parent do
                    local spd = eyeOpen and (eyeHot and 3.2 or 1.4) or 0.5
                    a = a + spd; b = b - spd * 0.8
                    fireA.Rotation = a
                    fireB.Rotation = b
                    fireSmoke.Rotation = a * 0.3
                    task.wait(0.05)
                end
            end)
        end
        -- The runes twinkle: each group flares on its own clock, in its own
        -- rhythm, brighter when the bot pilots.
        for i = 1, 4 do
            local layer = auraLayers["runes_s" .. i]
            if layer then
                task.spawn(function()
                    task.wait(i * 0.37)
                    while gui and gui.Parent do
                        if eyeOpen and auraRoot.Visible then
                            local up = 0.2 + math.random() * 0.4
                            tween(layer, up, { ImageTransparency = math.random() * 0.2 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                            task.wait(up + 0.05 + math.random() * 0.25)
                            local down = 0.5 + math.random() * 1.2
                            tween(layer, down, { ImageTransparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
                            task.wait(down + 0.2 + math.random() * 1.6)
                        else
                            task.wait(0.5)
                        end
                    end
                end)
            end
        end

        local function setEye(open, hot)
            if open == eyeOpen and hot == eyeHot then return end
            eyeOpen, eyeHot = open, hot
            local col = hot and BAD or ACCENT
            if fireA then
                fireA.ImageColor3 = hot and Color3.fromRGB(255, 80, 50) or TP.wisp
                fireB.ImageColor3 = hot and Color3.fromRGB(255, 120, 80) or TP.wisp
                fireSmoke.ImageColor3 = hot and Color3.fromRGB(200, 20, 10) or TP.smoke
            end
            if halo1 then halo1.BackgroundColor3 = col end
            if halo2 then halo2.BackgroundColor3 = col end
            auraTint(hot)
            if open then
                auraRoot.Visible = true
                setEyeTint(hot and Color3.new(1, 0.85, 0.85) or Color3.new(1, 1, 1), 0)
            else
                for _, e in ipairs(auraStrokes) do tween(e.stroke, 0.8, { Transparency = 1 }) end
                for _, img in pairs(auraLayers) do tween(img, 0.8, { ImageTransparency = 1 }) end
                task.delay(0.85, function() if not eyeOpen then auraRoot.Visible = false end end)
                setEyeTint(Color3.fromRGB(150, 140, 135), 0.35)
            end
            if auraSet then auraSet(open, hot) end
        end

        -- ----------------------------------------------------------- refresh
        local function refresh()
            local running = Config.Enabled and true or false
            local hpPct = math.floor(getHPPct() or 0)
            local hurt = running and hpPct > 0 and hpPct < (Config.RetreatHP or 25)
            setEye(running, hurt)

            local st = tostring(Bot.State or "IDLE")
            local stunned = false
            pcall(function() stunned = isStunned() or isRagdolled() or isDowned() end)
            if not running then
                l1.Text = TP.idle
                l1.TextColor3 = DIM
            else
                local word = stunned and "Stunned" or (STATE_WORD[st] or st)
                if not stunned then
                    if tick() < (Bot.KnowCounterUntil or 0) then word = "Parrying"
                    elseif st == "ATTACK" and Bot.TacConf then word = "Chaining"
                    elseif st == "ATTACK" and Bot.KnowSt == "block" then word = "Breaking guard"
                    elseif st == "ATTACK" and Bot.KnowSt == "rag" then word = "Standing over"
                    elseif st == "DEFEND" and tick() < (Bot.PreGuardUntil or 0) then word = "Bracing"
                    elseif st == "PUNISH" and Bot.PunishFromBlock and (tick() - Bot.PunishFromBlock) < 1.5 then word = "Countering" end
                end
                if hurt then word = word .. "  ·  bleeding" end
                l1.Text = word
                l1.TextColor3 = hurt and BAD or ACCENT2
            end

            if menu.Visible then syncMenu() end
        end

        FF_HUD_REFRESH = refresh

        task.spawn(function()
            local lastErr = 0
            while true do
                task.wait(0.15)
                if not gui or not gui.Parent then break end
                local ok, err = pcall(refresh)
                if not ok and tick() - lastErr > 5 then
                    lastErr = tick()
                    pcall(debug, "[HUD] refresh error: " .. tostring(err))
                end
            end
        end)

        bind(UserInputService.InputBegan, function(input, gameProcessedEvent)
            if gameProcessedEvent then return end
            if input.KeyCode == Enum.KeyCode.RightControl or input.KeyCode == Enum.KeyCode.F5 then
                toggleBot()
            elseif input.KeyCode == Enum.KeyCode.RightShift then
                pcall(function()
                    Bot.LockMode = "AUTO"
                    Bot.LockedName = nil
                    debug("[HUD] mark released (RightShift)")
                end)
            elseif input.KeyCode == Enum.KeyCode.Insert then
                setMenu(not menu.Visible)
            end
        end)

        pcall(refresh)

        -- Arrive: the eye and its words fade in from nothing.
        pcall(function()
            if eyeImg:IsA("ImageLabel") then
                local target = eyeImg.ImageTransparency
                eyeImg.ImageTransparency = 1
                tween(eyeImg, 1.4, { ImageTransparency = target }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            end
            l1.TextTransparency = 1
            tween(l1, 1.4, { TextTransparency = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        end)
    end

    Theme.rebuild = buildHUD
    local okB, errB = pcall(buildHUD)
    if not okB then
        debug("[HUD] build failed (engine still running): " .. tostring(errB))
        pcall(announce, "HUD failed to build - bot still runs; see log")
    end
end

announce("The Eye HUD on v91 - tap the eye for the menu, RightCtrl/F5 toggles, Insert opens the menu, RightShift releases the mark")















local lastDeathAt = 0

local function onDeath(char, source)
    if tick() - lastDeathAt < 3 then return end
    lastDeathAt = tick()




    if autoIsSwitching() then







        if (Life.moves or 0) == 0 and (Life.dmg or 0) == 0
           and (tick() - (Life.startAt or 0)) < (Config.SwitchWaitMax + Config.SwitchRespawnTimeout + 2) then
            Life.active = false
            debug("respawn was a character switch - life discarded (no fighting)")
        else
            debug("respawn was a character switch, not a death")
            memLifeEnd()
        end
        return
    end

    local h = char and char:FindFirstChild("HumanoidRootPart")
    local pos = Bot.LastAlivePos or (h and h.Position) or Bot.LastPos
    if pos then
        mapNoteDeath(pos)
    else
        debug("death: no position available, not recorded")
    end




    memNoteDeath(Bot.Target)
    memLifeEnd()
    autoOnDeath()
    memSave(true, "death")
    logFlush(true)

    if Config.Enabled then stopBot(); updateUI() end
end

local function hookDeath(char)
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
    if hum then
        hum.Died:Connect(function() onDeath(char, "Died") end)
    end
end







LocalPlayer.CharacterAdded:Connect(function(char)





    AutoState.spawnedAt = tick()
    AutoState.spawnHP = 0

    AutoState.wastedAt = -999
    AutoState.wastedBackoffUntil = 0






    Bot.DmgFrom = setmetatable({}, { __mode = "k" })
    Bot.Nemesis = nil
    Bot.NemesisDmg = 0


    Bot.GangedUntil = 0
    Bot.RejoinSince = 0

    memLifeStart()
    hookDeath(char)

    task.delay(0.4, function()

        AutoState.spawnHP = getHP() or 0
    end)

    task.delay(0.5, function() autoOnSpawn(char) end)
end)


hookDeath(LocalPlayer.Character)










AutoState.spawnedAt = tick()
AutoState.spawnHP = getHP() or 0

LocalPlayer.CharacterRemoving:Connect(function(char)
    onDeath(char, "Removing")
end)



